  `merchant_name` varchar(256) NOT NULL COMMENT '参与方中信签约名称快照',
  `amount` decimal(18,2) NOT NULL COMMENT '参与方收款或分润金额',
  `create_user_id` bigint(20) NULL COMMENT '创建人ID',
  `create_user_name` varchar(64) NULL COMMENT '创建人姓名',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_user_id` bigint(20) NULL COMMENT '更新人ID',
  `update_user_name` varchar(64) NULL COMMENT '更新人姓名',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bigint(20) NOT NULL DEFAULT 0 COMMENT '是否删除，0正常，非0为被删除行ID',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_request_party` (`request_id`, `party_role`, `party_index`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='中信转账请求的主收款方和分润方快照，通用支持最多四个分润方'
;

CREATE TABLE `demeter_citic_transfer_request` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `biz_type` varchar(32) NOT NULL COMMENT '业务类型，采师费为PICKUP_FEE',
  `biz_no` varchar(64) NOT NULL COMMENT '业务编号，采师费为内部付款申请号',
  `request_kind` varchar(16) NOT NULL COMMENT '请求类型：TRANSFER=转账，QUERY=查单',
  `parent_request_id` bigint(20) NULL COMMENT '查单请求关联的原始转账请求ID，转账请求为空',
  `trans_code` varchar(16) NOT NULL COMMENT '中信交易码：21000050或21000010',
  `req_ssn` varchar(64) NOT NULL COMMENT '发起方请求流水号，每次银行请求唯一',
  `attempt_no` int(11) NOT NULL COMMENT '同一业务同一请求类型下的请求序号，从1开始',
  `buss_id` varchar(64) NOT NULL COMMENT '中信业务订单号快照，明确失败重试保持不变',
  `buss_sub_id` varchar(64) NOT NULL COMMENT '中信业务子订单号快照，明确失败重试保持不变',
  `payer_merchant_no` varchar(64) NOT NULL COMMENT '付款方中信商户号快照',
  `payer_merchant_name` varchar(256) NOT NULL COMMENT '付款方中信签约名称快照',
  `amount` decimal(18,2) NOT NULL COMMENT '本次请求金额',
  `fund_type` varchar(32) NOT NULL COMMENT '中信资金类型',
  `request_trans_date` varchar(8) NOT NULL COMMENT '原请求交易日期，格式yyyyMMdd，UNKNOWN查单使用',
  `request_trans_time` varchar(6) NOT NULL COMMENT '原请求交易时间，格式HHmmss',
  `status` varchar(32) NOT NULL COMMENT '请求状态：INIT、SUCCESS、EXPLICIT_FAIL、UNKNOWN、PROCESSING',
  `rsp_code` varchar(64) NULL COMMENT '银行应答码',
  `rsp_msg` varchar(512) NULL COMMENT '银行应答说明',
  `user_ssn` varchar(64) NULL COMMENT '中信侧交易流水号',
  `bank_trans_date` varchar(8) NULL COMMENT '银行侧交易日期，格式yyyyMMdd',
  `bank_trans_time` varchar(6) NULL COMMENT '银行侧交易时间，格式HHmmss',
  `request_snapshot` text NULL COMMENT '已脱敏且移除SIGN_INFO的请求报文快照',
  `response_snapshot` text NULL COMMENT '已脱敏且移除SIGN_INFO的响应报文快照',
  `started_at` datetime NULL COMMENT '银行调用开始时间',
  `finished_at` datetime NULL COMMENT '银行调用完成时间',
  `error_type` varchar(64) NULL COMMENT '调用错误分类，用于区分明确失败和结果未知',
  `create_user_id` bigint(20) NULL COMMENT '创建人ID',
  `create_user_name` varchar(64) NULL COMMENT '创建人姓名',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_user_id` bigint(20) NULL COMMENT '更新人ID',
  `update_user_name` varchar(64) NULL COMMENT '更新人姓名',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bigint(20) NOT NULL DEFAULT 0 COMMENT '是否删除，0正常，非0为被删除行ID',
  PRIMARY KEY (`id`),
  KEY `nk_parent` (`parent_request_id`, `deleted`),
  KEY `nk_unknown` (`status`, `deleted`, `update_time`, `id`),
  KEY `nk_user_ssn` (`user_ssn`, `deleted`),
  UNIQUE KEY `uk_biz_attempt` (`biz_type`, `biz_no`, `request_kind`, `attempt_no`),
  UNIQUE KEY `uk_req_ssn` (`req_ssn`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='通用中信转账及查单请求记录，不绑定具体业务实现'
;

CREATE TABLE `demeter_company_pay_config` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `company_id` bigint(20) NOT NULL COMMENT '省区id',
  `type` varchar(32) NOT NULL COMMENT '配置类型',
  `merchant_no` varchar(64) NULL COMMENT '企业商编，E商编',
  `config_value` text NULL COMMENT '配置内容',
  `status` tinyint(4) NOT NULL DEFAULT 0 COMMENT '是否有效',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `NK_COMPANY_TYPE_IDX` (`company_id`, `type`),
  KEY `NK_MERCHANT_IDX` (`merchant_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4
;

CREATE TABLE `demeter_copy` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `one` int(11) NULL,
  `two` int(11) NULL,
  `three` int(11) NULL,
  `four` int(11) NULL,
  `five` int(11) NULL,
  `six` int(11) NULL,
  `server` int(11) NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4
;

CREATE TABLE `demeter_copy_copy1` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `one` int(11) NULL,
  `two` int(11) NULL,
  `three` int(11) NULL,
  `four` int(11) NULL,
  `five` int(11) NULL,
  `six` int(11) NULL,
  `server` int(11) NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4
;

CREATE TABLE `demeter_large_pay_apply_stash` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `company_id` bigint(20) NOT NULL,
  `pay_apply_series_no` varchar(200) NOT NULL,
  `pay_apply_json` longtext NOT NULL,
  `payment_pay_out_no` varchar(200) NOT NULL,
  `execute` tinyint(4) NOT NULL,
  `status` varchar(50) NOT NULL DEFAULT 'NOT_EXE',
  `failed_reason` varchar(255) NULL,
  `create_time` datetime NOT NULL,
  `update_time` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `se_no` (`pay_apply_series_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4
;

CREATE TABLE `demeter_large_top_up_hlb_config` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `out_bank_name` varchar(100) NOT NULL COMMENT '出款银行',
  `in_bank_name` varchar(100) NOT NULL,
  `open_account_name` varchar(100) NOT NULL,
  `time_config` longtext NULL,
  `low_water_mark_amount` decimal(10,2) NOT NULL DEFAULT 0.00,
  `collection_point` varchar(100) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='HLB大额支付充值配置表'
;

CREATE TABLE `demeter_llp_refund_task` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `origin_order_no` varchar(64) NOT NULL COMMENT '原支付商户订单号 no_order',
  `status` enum('INIT','SENT','FAILED','UNKNOW_STATS') NOT NULL DEFAULT 'INIT' COMMENT 'INIT待发送，SENT已发送，FAILED发送失败',
  `amount` decimal(16,2) NOT NULL COMMENT '退款金额，单位元',
  `payload` longtext NOT NULL COMMENT '完整退款请求JSON，包含no_refund',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_origin_status` (`origin_order_no`, `status`),
  KEY `idx_status_id_origin` (`status`, `id`, `origin_order_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='连连退款请求队列'
;

CREATE TABLE `demeter_llp_refund_task_bench` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `origin_order_no` varchar(64) NOT NULL COMMENT '同组原订单号相同',
  `status` enum('INIT','SENT','FAILED') NOT NULL DEFAULT 'INIT',
  `amount` decimal(16,2) NOT NULL,
  `payload` longtext NOT NULL,
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_origin_status` (`origin_order_no`, `status`),
  KEY `idx_status_id_origin` (`status`, `origin_order_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='连连退款查询性能测试数据'
;

CREATE TABLE `demeter_merchant` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `company_id` bigint(20) NOT NULL COMMENT '所属企业',
  `company_type` varchar(64) NOT NULL DEFAULT 'USER' COMMENT '类型, PLATFORM: 平台商户, USER: 用户',
  `mer_passowrd` varchar(64) NOT NULL COMMENT '账户密码',
  `merchant_type` varchar(20) NOT NULL COMMENT '商户类型',
  `merchant_category` varchar(35) NOT NULL COMMENT '经营类别',
  `industry_type_code` varchar(10) NULL COMMENT '行业类型编码',
  `micro_biz_type` varchar(20) NULL COMMENT '小微经营类型',
  `sign_name` varchar(150) NULL COMMENT '子商户签约名',
  `show_name` varchar(100) NULL COMMENT '展示名（收银台展示名）',
  `legal_person` varchar(20) NOT NULL COMMENT '法人名字',
  `legal_person_iD` varchar(30) NOT NULL COMMENT '法人身份证号',
  `legal_person_phone_no` varchar(20) NULL COMMENT '法人手机号',
  `org_num` varchar(30) NOT NULL COMMENT '组织机构代码',
  `business_license` varchar(30) NOT NULL COMMENT '营业执照号',
  `linkman` varchar(15) NOT NULL COMMENT '联系人',
  `link_phone` varchar(20) NOT NULL COMMENT '联系电话',
  `email` varchar(50) NOT NULL COMMENT '联系邮箱',
  `pro_region_code` varchar(8) NULL COMMENT '区县编码省',
  `pro_region_name` varchar(50) NULL COMMENT '区县编码',
  `city_region_code` varchar(8) NULL COMMENT '区县编码市',
  `city_region_name` varchar(50) NULL COMMENT '区县编码',
  `region_name` varchar(50) NULL COMMENT '区县编码',
  `region_code` varchar(8) NOT NULL COMMENT '区县编码',
  `address` varchar(150) NOT NULL COMMENT '通讯地址',
  `id_type` varchar(20) NULL COMMENT '法人证件类型',
  `settlement_calc_type` varchar(20) NULL COMMENT '结算产品类型',
  `settlement_calc_type_d0` varchar(20) NULL COMMENT '结算产品类型-加急',
  `settle_bank_type` varchar(20) NULL COMMENT '结算卡类型',
  `settlement_period` varchar(20) NOT NULL COMMENT '结算类型',
  `settlement_mode` varchar(20) NOT NULL COMMENT '结算方式',
  `settlement_remark` varchar(100) NULL COMMENT '结算备注',
  `settle_mode` varchar(60) NOT NULL COMMENT '结算模式',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '修改时间',
  `update_user_id` bigint(20) NULL COMMENT '最后修改人',
  `update_user_name` varchar(32) NULL COMMENT '最后修改人',
  `settle_fee_type` varchar(32) NULL COMMENT '手续费类型',
  `deposit_type` varchar(32) NOT NULL DEFAULT 'NOT_FIXED_DEPOSIT' COMMENT '保证金类型',
  `deposit` decimal(20,2) NOT NULL DEFAULT 0.00 COMMENT '保证金',
  `seller_settlement_type` varchar(30) NOT NULL DEFAULT 'DELIVERY_DATE' COMMENT '卖家结算类型',
  `settle_cycle` int(11) NOT NULL DEFAULT 7 COMMENT '卖家结算周期',
  `commission_rate` decimal(20,2) NOT NULL DEFAULT 0.00 COMMENT '抽佣比例',
  `face_to_face_settle_cycle` int(11) NOT NULL DEFAULT 1 COMMENT '面对面交易结算周期',
  `face_to_face_commission_rate` decimal(12,2) NOT NULL DEFAULT 0.00 COMMENT '面对面交易抽佣比例',
  `reservation_amount_rate` decimal(5,2) NOT NULL DEFAULT 20.00 COMMENT '预留金额比例',
  `reservation_amount_rate_flag` tinyint(4) NOT NULL DEFAULT 0 COMMENT '单设预留金额比例',
  `person_expire_start_date` varchar(12) NULL COMMENT '身份证过期开始时间',
  `person_expire_end_date` varchar(12) NULL COMMENT '身份证过期结束时间',
  `cert_expire_start_date` varchar(12) NULL COMMENT '营业执照过期起始时间',
  `cert_expire_end_date` varchar(12) NULL COMMENT '营业执照过期结束时间',
  `source_type` varchar(60) NULL COMMENT '来源',
  PRIMARY KEY (`id`),
  KEY `NK_COMPANY_IDX` (`company_id`),
  UNIQUE KEY `UK_EMAIL_IDX` (`email`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='合利宝商户资质'
;

CREATE TABLE `demeter_merchant_account_bill` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `merchant_id` bigint(20) NOT NULL COMMENT '商户ID',
  `merchant_no` varchar(50) NOT NULL COMMENT '商户商编',
  `sign_name` varchar(150) NULL COMMENT '商户签约名',
  `company_id` bigint(20) NOT NULL COMMENT '企业ID',
  `operation_type` varchar(10) NOT NULL COMMENT '操作类型，SPLIT_BILL：分账，SETTLEMENT：结算',
  `trade_amount` decimal(10,2) NULL COMMENT '交易金额',
  `trade_desc` varchar(50) NULL COMMENT '交易描述',
  `income_expenditure` varchar(10) NULL COMMENT '收入/支出，对于结算来说是支出',
  `pay_type_code` varchar(32) NULL COMMENT '支付方式CODE，WX_PAY：微信支付，VIRTUAL_PAY：虚拟支付，手动提现为空',
  `payment_channel_type` varchar(30) NOT NULL DEFAULT 'HLB' COMMENT '支付渠道',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_merchant_company_income` (`merchant_id`, `company_id`, `income_expenditure`, `payment_channel_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4
;

CREATE TABLE `demeter_merchant_account_bill_apply` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `payment_apply_serial_no` varchar(64) NOT NULL COMMENT '支付流水号',
  `payment_type` varchar(32) NOT NULL COMMENT '支付方式，WX_PAY：微信支付，VIRTUAL_PAY：虚拟支付，手动提现为空',
  `payment_channel_type` varchar(32) NOT NULL COMMENT '支付渠道',
  `income_expenditure` varchar(32) NOT NULL COMMENT '收入或者支出',
  `split_bill_success` varchar(32) NOT NULL COMMENT '分账是否成功，SUCCESS：成功，FAILED：失败',
  `handle_status` varchar(64) NOT NULL COMMENT '处理状态',
  `payment_callback_content` mediumtext NULL COMMENT '支付回调内容',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '记账时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_serial_no_payment_type` (`payment_apply_serial_no`, `payment_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='结算账单申请表'
;

CREATE TABLE `demeter_merchant_account_bill_apply_order_log` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `payment_apply_serial_no` varchar(64) NOT NULL COMMENT '支付流水号',
  `order_no` varchar(64) NOT NULL COMMENT '订单号',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '记账时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_payment_apply_serial_no_order_no` (`payment_apply_serial_no`, `order_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='结算账单订单申请日志表'
;

CREATE TABLE `demeter_merchant_account_bill_detail` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `merchant_account_bill_id` bigint(20) NOT NULL COMMENT '账户主键ID',
  `settlement_id` bigint(20) NOT NULL DEFAULT -1 COMMENT '结算记录主键ID',
  `order_number` varchar(64) NULL COMMENT '订单号',
  `goods_id` bigint(20) NULL COMMENT '商品id',
  `payment_apply_serial_no` varchar(64) NULL COMMENT '支付流水号',
  `trade_type` varchar(64) NULL COMMENT '交易类型',
  `settlement` varchar(30) NOT NULL COMMENT '是否结算，SETTLED：已结算，PENDING_SETTLEMENT：待结算',
  `split_bill_success` varchar(10) NOT NULL COMMENT '分账是否成功，SUCCESS：成功，FAILED：失败',
  `statement_date` date NULL COMMENT '归属日期',
  `settlement_date` datetime NULL COMMENT '结算日期',
  `order_clearing_source_type` varchar(100) NOT NULL DEFAULT 'GOODS_AMOUNT' COMMENT '订单清分费用来源类型',
  `order_cost_sharing_account_type` varchar(100) NULL COMMENT '费用分摊账户类型',
  `sale_company_id` bigint(20) NULL COMMENT '销售企业id',
  `create_time` datetime NOT NULL COMMENT '记账时间',
  `update_time` datetime NULL COMMENT '最后修改时间',
  PRIMARY KEY (`id`),
  KEY `idx_merchant_account_id_settle` (`merchant_account_bill_id`),
  KEY `idx_order_no` (`order_number`),
  KEY `idx_settlement_date` (`settlement_date`),
  KEY `idx_settlement_id` (`settlement_id`),
  KEY `idx_statement_date` (`statement_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4
;

CREATE TABLE `demeter_merchant_account_bill_order_summary` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `merchant_id` bigint(20) NOT NULL COMMENT '商户id',
  `order_id` bigint(20) NOT NULL COMMENT '订单id',
  `order_no` varchar(64) NOT NULL COMMENT '订单号',
  `statement_date` date NOT NULL COMMENT '归属日期',
  `clearing_summary_info` mediumtext NULL COMMENT '清分汇总明细',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '最后修改时间',
  PRIMARY KEY (`id`),
  KEY `idx_merchant_id_order_no` (`merchant_id`, `order_no`),
  UNIQUE KEY `uk_merchant_id_order_id` (`merchant_id`, `order_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='商户订单清分数据汇总'
;

