  `create_time` datetime NOT NULL COMMENT '记账时间',
  `update_time` datetime NOT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_create_time` (`merchant_id`, `create_time`, `trade_type`),
  KEY `idx_merchant_settle_date` (`merchant_id`, `settlement`, `settlement_date`, `income_expenditure`, `payment_apply_serial_no`),
  KEY `idx_merchant_statement_date` (`merchant_id`, `statement_date`, `settlement`, `income_expenditure`),
  KEY `idx_payment_apply_serial_no` (`payment_apply_serial_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='按保证金方式结算-标果湖南'
;

