CREATE TABLE `demeter_merchant_account_bill_pro_settle_log` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `merchant_id` bigint(20) NOT NULL COMMENT '商户ID',
  `merchant_no` varchar(50) NOT NULL COMMENT '商户商编',
  `sign_name` varchar(150) NULL COMMENT '商户签约名',
  `settle_amount` decimal(12,2) NOT NULL COMMENT '结算金额',
  `req_sn` varchar(68) NULL COMMENT '请求流水单号',
  `inner_settlement_no` varchar(68) NULL,
  `out_settlement_no` varchar(50) NOT NULL COMMENT '外部结算号',
  `ext_info` varchar(255) NULL COMMENT '扩展信息',
  `thrid_sn` varchar(68) NULL COMMENT '三方单号',
  `biz_sn` varchar(68) NULL COMMENT '业务单号',
  `account_name` varchar(50) NOT NULL COMMENT '结算账户名',
  `account_no` varchar(32) NOT NULL COMMENT '结算卡联行号',
  `fee` decimal(8,2) NOT NULL COMMENT '手续费',
  `to_account_amount` decimal(10,2) NOT NULL COMMENT '到账金额',
  `settlement_date` datetime NOT NULL COMMENT '结算日期',
  `to_account_date` datetime NULL COMMENT '到账时间',
  `status` varchar(15) NOT NULL COMMENT '打卡状态',
  `ret_msg` varchar(50) NULL COMMENT '返回信息',
  `fail_reason` varchar(100) NULL COMMENT '失败原因',
  `settle_operation_type` varchar(32) NOT NULL COMMENT '结算操作类型，AUTONOMY_SETTLE：自主结算，SYSTEM_RETRY_SETTLE：系统重试结算',
  `retry_status` varchar(32) NOT NULL COMMENT '重试状态，NO_RETRY：未重试，ALREADY_RETRY：已重试',
  `payment_channel_type` varchar(20) NOT NULL COMMENT '支付渠道',
  `company_id` bigint(20) NOT NULL COMMENT '企业ID',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '更新时间',
  `deleted` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否删除',
  PRIMARY KEY (`id`),
  KEY `idx_sn` (`out_settlement_no`),
  KEY `idx_status_type` (`status`, `payment_channel_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4
;

CREATE TABLE `demeter_merchant_account_bill_settle_date` (
