;

CREATE TABLE `demeter_merchant_balance_snapshot` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `merchant_id` bigint(20) NOT NULL COMMENT '商户id',
  `seller_type` varchar(50) NOT NULL COMMENT '商户在系统中的类型：BUYER，BUSINESS',
  `seller_id` bigint(20) NOT NULL COMMENT '卖家或者买手id',
  `seller_name` varchar(100) NULL COMMENT '卖家或者买手名称',
  `company_id` bigint(20) NOT NULL COMMENT '企业id',
  `seller_company_id` bigint(20) NOT NULL COMMENT '卖家企业id',
  `hj_balance` decimal(10,2) NOT NULL COMMENT '汇聚账户余额',
  `hj_balance_reason` varchar(512) NULL COMMENT '汇聚查询余额失败原因',
  `hlb_balance` decimal(10,2) NOT NULL COMMENT '合利宝账户余额',
  `hlb_balance_reason` varchar(512) NULL COMMENT '合利宝查询余额失败原因',
  `hlb_ea_balance` decimal(10,2) NOT NULL COMMENT '合利宝电子户余额',
  `hlb_ea_balance_reason` varchar(512) NULL COMMENT '合利宝电子户查询余额失败原因',
