  `order_no` varchar(50) NOT NULL COMMENT '进件商户订单号',
  `entry_status` varchar(15) NULL COMMENT '进件状态',
  `sign_status` tinyint(4) NULL DEFAULT 0 COMMENT '是否签约',
  `authorization_flag` tinyint(4) NULL DEFAULT 1 COMMENT 'true代表授权, false代表不授权',
  `provisions_no` varchar(150) NULL COMMENT '被服金账户号',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '修改时间',
  `update_user_id` bigint(20) NULL COMMENT '最后修改人',
  `update_user_name` varchar(32) NULL COMMENT '最后修改人',
  `transfer_product_flag` tinyint(4) NOT NULL DEFAULT 0 COMMENT '代付功能, 0:未开通, 1:已开通',
  `transfer_product_remark` varchar(255) NULL COMMENT '代付功能开通说明',
  `virtual_transfer_product_flag` tinyint(4) NOT NULL DEFAULT 0 COMMENT '虚拟转账功能, 0:未开通, 1:已开通',
  `fail_remark` varchar(512) NULL COMMENT '进件状态说明',
  `status` int(11) NOT NULL DEFAULT -1 COMMENT '状态，生效为0，失效=id',
  PRIMARY KEY (`id`),
  KEY `NK_MERCHANT_NO_IDX` (`merchant_no`),
  UNIQUE KEY `UK_MERCHANT_ID_STATUS` (`merchant_id`, `status`),
  UNIQUE KEY `UK_ORDER_NO_IDX` (`order_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='合利宝支付信息表'
;

CREATE TABLE `demeter_merchant_detail_hlb_ea` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `merchant_id` bigint(20) NOT NULL,
  `merchant_type` varchar(32) NULL COMMENT '商户类型',
  `ea_merchant_type` varchar(32) NULL COMMENT '电子商户类型',
  `id_card` varchar(100) NOT NULL COMMENT '证件号，用于标识账号唯一性',
  `user_id` varchar(50) NOT NULL COMMENT '用于电子户的用户id',
  `payment_pass` varchar(128) NOT NULL COMMENT '用于电子户交易的密码',
  `sys_user_id` varchar(50) NULL COMMENT '合利宝平台的用户编号',
  `user_status` varchar(20) NULL COMMENT '用户状态, INIT-入网中; EDIT - 编辑中; AUDITING-待审核; ACTIVE-正常; AUDIT_FAIL-拒绝; SIGNING - 待签约
',
  `return_message` varchar(255) NULL COMMENT '业务代码说明',
  `virtual_account_no` varchar(50) NULL COMMENT '银行电子账户',
  `account_name` varchar(255) NULL COMMENT '账户名称',
  `merchant_channel_status` varchar(10) NULL COMMENT '银行报备状态, INIT:初始化, DOING:处理中, FAIL:失败, SUCCESS:报备成功
',
  `bank_card_id` varchar(50) NULL COMMENT '银行卡ID',
  `settle_bank_type` varchar(100) NULL COMMENT '结算卡类型',
  `phone` varchar(20) NULL COMMENT '冗余一个手机号, 仅用于电子户使用',
  `bind_status` varchar(32) NULL COMMENT '对公账户的绑定状态',
  `remark` varchar(2048) NULL COMMENT '备注',
  `status` tinyint(4) NOT NULL DEFAULT 1 COMMENT '启用/禁用状态, 1:启用, 0:禁用',
  `deleted` tinyint(4) NOT NULL DEFAULT 0 COMMENT '是否删除，0:正常, 1:删除',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL COMMENT '修改时间',
  `create_user_id` bigint(20) NULL COMMENT '创建人id',
  `create_user_name` varchar(32) NULL COMMENT '创建人',
  `update_user_id` bigint(20) NULL COMMENT '最后修改人id',
  `update_user_name` varchar(32) NULL COMMENT '最后修改人',
  `final_clear` int(11) NULL DEFAULT 0 COMMENT '最终清理',
  `account_close_ret_code` varchar(50) NULL COMMENT '帐号关闭ret_code',
  `account_close_ret_msg` varchar(255) NULL COMMENT '账户关闭返回code',
  `account_close_error_msg` text NULL COMMENT '异常信息',
  PRIMARY KEY (`id`),
  KEY `idx_id_card` (`id_card`),
  UNIQUE KEY `uk_merchant_id_user_id` (`merchant_id`, `user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='合利宝电子户详情'
;

CREATE TABLE `demeter_merchant_ea_account_hlb` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `merchant_id` bigint(20) NOT NULL COMMENT '商户ID',
  `merchant_no` varchar(50) NULL COMMENT '商户商编',
  `ea_merchant_type` varchar(32) NULL COMMENT '电子商户类型',
  `balance` decimal(18,2) NOT NULL COMMENT '账户总余额',
  `frozen_balance` decimal(18,2) NOT NULL COMMENT '冻结余额',
  `available_balance` decimal(18,2) NOT NULL COMMENT '可用余额',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_merchant_no` (`merchant_no`),
  UNIQUE KEY `uk_merchant_id` (`merchant_id`),
  UNIQUE KEY `uk_merchant_no` (`merchant_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='商户-合利宝-生息账户表'
;

CREATE TABLE `demeter_merchant_ea_account_transaction_callback_log_hlb` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `merchant_no` varchar(50) NULL COMMENT '商户商编',
  `order_id` varchar(50) NOT NULL COMMENT '业务订单号',
  `serial_number` varchar(50) NOT NULL DEFAULT '' COMMENT '平台流水号',
  `amount` decimal(18,2) NOT NULL COMMENT '金额',
  `status` varchar(10) NOT NULL COMMENT '状态',
  `content` varchar(1000) NULL COMMENT '回调内容',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_merchant_no_order_id` (`merchant_no`, `order_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='商户-回调记录表'
;

CREATE TABLE `demeter_merchant_ea_account_transaction_hlb` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `merchant_id` bigint(20) NOT NULL COMMENT '商户ID',
  `merchant_no` varchar(50) NOT NULL COMMENT '商户商编',
  `biz_apply_no` varchar(50) NOT NULL COMMENT '业务订单号',
  `transaction_no` varchar(50) NOT NULL COMMENT '请求合力宝订单号',
  `serial_number` varchar(50) NOT NULL DEFAULT '' COMMENT '合力宝返回流水号',
  `transaction_type` varchar(20) NOT NULL COMMENT 'IN-转入,OUT-转出',
  `amount` decimal(18,2) NOT NULL COMMENT '金额',
  `adjust_before_amount` decimal(18,2) NULL COMMENT '变动前金额',
  `adjust_after_amount` decimal(18,2) NULL COMMENT '变动后金额',
  `status` varchar(10) NOT NULL COMMENT '状态',
  `remark` varchar(1000) NULL COMMENT '备注',
  `create_date` varchar(50) NULL COMMENT '合力宝订单创建时间',
  `complete_date` varchar(50) NULL COMMENT '合力宝订单完成时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_merchant_id` (`merchant_id`),
  KEY `idx_merchant_no` (`merchant_no`),
  KEY `idx_serial_number` (`serial_number`),
  UNIQUE KEY `uk_transaction_no` (`transaction_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='商户-合力宝生息账户流水表'
;

CREATE TABLE `demeter_merchant_file` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `merchant_id` bigint(20) NOT NULL COMMENT '进件id',
  `order_no` varchar(50) NOT NULL COMMENT '请求单号',
  `credential_type` varchar(64) NOT NULL COMMENT '资质附件类型',
  `credential_url` varchar(512) NOT NULL COMMENT '图片地址',
  `deleted` bigint(20) NOT NULL DEFAULT 0 COMMENT '是否删除',
  `status` varchar(20) NULL DEFAULT 0 COMMENT '图片进件状态',
  `remark` varchar(255) NULL COMMENT '描述',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `NK_QUALIFY_IDX` (`merchant_id`),
  UNIQUE KEY `UK_QUALIFY_TYPX_IDX` (`merchant_id`, `credential_type`, `deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4
;

CREATE TABLE `demeter_merchant_funds_pool` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `merchant_id` bigint(20) NOT NULL COMMENT '商户ID',
  `company_id` bigint(20) NOT NULL COMMENT '公司ID',
  `funds_pool` decimal(12,2) NOT NULL COMMENT '资金池(可结算)',
  `payment_channel_type` varchar(10) NOT NULL COMMENT '支付渠道',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_merchant_id` (`merchant_id`, `payment_channel_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='商户账户资金池'
;

CREATE TABLE `demeter_merchant_funds_pool_copy1` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `merchant_id` bigint(20) NOT NULL COMMENT '商户ID',
  `company_id` bigint(20) NOT NULL COMMENT '公司ID',
  `funds_pool` decimal(12,2) NOT NULL COMMENT '资金池(可结算)',
  `payment_channel_type` varchar(10) NOT NULL COMMENT '支付渠道',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_merchant_id` (`merchant_id`, `payment_channel_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='商户账户资金池'
;

CREATE TABLE `demeter_merchant_funds_pool_log` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `merchant_id` bigint(20) NOT NULL COMMENT '商户ID',
  `income_expenditure` varchar(10) NOT NULL COMMENT '收入/支出，对于结算来说是支出',
  `amount` decimal(12,2) NOT NULL COMMENT '金额',
  `operate_type` varchar(32) NOT NULL COMMENT '操作类型',
  `change_amount_before` decimal(12,2) NOT NULL COMMENT '变动之前金额',
  `change_amount_after` decimal(12,2) NOT NULL COMMENT '变动之后金额',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `apply_serial_no` varchar(128) NULL COMMENT '申请流水号',
  PRIMARY KEY (`id`),
  KEY `idx_merchant_time` (`merchant_id`, `create_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4
;

CREATE TABLE `demeter_merchant_hlb_ea_process_record` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `merchant_id` bigint(20) NOT NULL,
  `business_process_method` varchar(64) NOT NULL COMMENT '业务处理方法',
  `data` text NULL COMMENT '业务数据',
  `fail_count` tinyint(4) NOT NULL DEFAULT 0 COMMENT '失败次数, 默认最多重试5次',
  `remark` varchar(2048) NULL COMMENT '备注',
  `state` varchar(20) NOT NULL COMMENT '处理状态, NOT_DEAL:待处理, PROCESSING:处理中, SUCCESS:成功, FAILURE:失败',
  `deleted` tinyint(4) NOT NULL DEFAULT 0 COMMENT '是否删除，0:正常, 1:删除',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL COMMENT '修改时间',
  PRIMARY KEY (`id`),
  KEY `IDX_MERCHANT` (`merchant_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='合利宝电子户处理过程'
;

CREATE TABLE `demeter_merchant_industry_type` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `code` varchar(10) NOT NULL COMMENT '类别编码',
  `name` varchar(100) NOT NULL COMMENT '类别名称',
  `type` varchar(20) NULL COMMENT '商户经营类型',
  `biz_type` varchar(100) NULL COMMENT '业务类型',
  `licence` varchar(200) NULL COMMENT '必传经营许可证',
  `deleted` tinyint(4) NULL DEFAULT 0,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4
;

CREATE TABLE `demeter_merchant_modify_apply` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `merchant_id` bigint(20) NOT NULL,
  `merchant_no` varchar(20) NOT NULL COMMENT '商户no',
  `order_no` varchar(50) NOT NULL COMMENT '申请订单号',
  `content` text NULL COMMENT '申请内容',
  `result` varchar(200) NULL COMMENT '审核状态结果',
  `alteration_status` varchar(20) NULL COMMENT '审核状态',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  `create_user_id` bigint(20) NOT NULL COMMENT '操作人',
  `create_user_name` varchar(32) NULL COMMENT '操作人',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4
;

CREATE TABLE `demeter_merchant_open_apply_attach` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `biz_type` varchar(50) NOT NULL COMMENT '业务类型',
  `biz_id` bigint(20) NOT NULL COMMENT '业务id',
  `attach_type` varchar(50) NOT NULL COMMENT '附件类型',
  `attach_url` varchar(255) NOT NULL COMMENT '附件地址',
  `media_type` varchar(50) NOT NULL DEFAULT 'PICTURE' COMMENT '媒体类型',
  `settle_bank_type` varchar(50) NOT NULL COMMENT '卡类型',
  `create_user_id` bigint(20) NOT NULL COMMENT '创建人id',
  `create_user_name` varchar(50) NULL,
  `create_time` datetime NOT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_type` (`biz_type`, `biz_id`, `attach_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='商户进件申请附近表'
;

CREATE TABLE `demeter_merchant_oper_log` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `merchant_id` bigint(20) NOT NULL,
  `oper_type` varchar(32) NULL COMMENT '变更操作',
  `merchant_entry_alteration_type` varchar(20) NOT NULL COMMENT '变更类型',
  `status` tinyint(4) NOT NULL DEFAULT 0 COMMENT '变更执行状态',
  `content` text NULL COMMENT '变更内容',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `create_user_id` bigint(20) NOT NULL COMMENT '创建人',
  `create_user_name` varchar(32) NULL COMMENT '创建人',
  PRIMARY KEY (`id`),
  KEY `NK_QUALIFY_IDX` (`merchant_id`),
  KEY `NK_QUALIFY_TYPE_IDX` (`merchant_id`, `merchant_entry_alteration_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4
;

CREATE TABLE `demeter_merchant_regions` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `code` varchar(8) NOT NULL COMMENT '地址码',
  `name` varchar(50) NOT NULL COMMENT 'name',
  `parent_code` varchar(8) NULL COMMENT '上级地址码',
  `code_level` varchar(10) NULL COMMENT '级别',
  `deleted` tinyint(4) NULL DEFAULT 0,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4
;

CREATE TABLE `demeter_merchant_settle_compensate` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `account_bill_id` bigint(20) NOT NULL COMMENT 'demeter_merchant_account_bill_detail主键ID',
  `company_id` bigint(20) NULL COMMENT '企业ID',
  `order_number` varchar(64) NULL COMMENT '订单号',
  `trade_amount` decimal(10,2) NULL DEFAULT 0.00 COMMENT '分账失败交易金额',
  `sale_refund_amount` decimal(10,2) NULL DEFAULT 0.00 COMMENT '退款金额',
  `merchant_no` varchar(15) NULL COMMENT '商户号',
  `transfer_order_id` varchar(50) NULL COMMENT '转账订单号',
  `status` varchar(32) NULL COMMENT '处理状态',
  `fail_reason` varchar(255) NULL COMMENT '失败原因',
  `settlement_date` datetime NULL COMMENT '结算日期',
  `create_time` datetime NULL COMMENT '创建时间',
  `update_time` datetime NULL COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_transfer_order_id` (`transfer_order_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4
;

CREATE TABLE `demeter_merchant_settle_compensate_transfer` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `account_bill_detail_id` bigint(20) NOT NULL,
  `transfer_order_id` varchar(50) NULL COMMENT '交易订单号',
  `merchant_source_no` varchar(32) NULL COMMENT '出账商户号',
  `merchant_no` varchar(32) NOT NULL COMMENT '商户编号',
  `company_id` bigint(20) NOT NULL COMMENT '企业ID',
  `trade_amount` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '转账金额',
  `in_company_id` bigint(20) NULL COMMENT '入账账户的企业id',
  `status` varchar(32) NOT NULL DEFAULT 'NO_PROCESS' COMMENT 'NO_PROCESS:未处理，RUNNING_PROCESS：处理中，ALREADY_PROCESS：已处理',
  `need_insert_bill` tinyint(4) NOT NULL DEFAULT 0 COMMENT '是否需要插入流水',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL COMMENT '修改时间',
  `bill_date` varchar(32) NULL COMMENT '账期',
  `transfer_fee_type` varchar(32) NOT NULL COMMENT '转账费用类型',
  PRIMARY KEY (`id`),
  KEY `idx_order_id` (`transfer_order_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4
;

CREATE TABLE `demeter_merchant_settlement_card` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `merchant_id` bigint(20) NOT NULL COMMENT '商户id',
  `order_no` varchar(50) NOT NULL COMMENT '商户订单号',
  `account_name` varchar(50) NOT NULL COMMENT '开户人名称',
  `account_no` varchar(30) NOT NULL COMMENT '结算卡号',
  `settle_bank_type` varchar(20) NOT NULL COMMENT '结算卡类型',
  `bank_code` varchar(13) NOT NULL COMMENT '结算卡联行号',
  `bank_name` varchar(50) NULL COMMENT '银行名称',
  `bank_reserved_phone` varchar(20) NULL COMMENT '银行预留手机号',
  `front_id_card` varchar(512) NULL COMMENT '身份证正面',
  `back_id_card` varchar(512) NULL COMMENT '身份证反面',
  `hand_id_card` varchar(512) NULL COMMENT '手持身份证',
  `hand_bank_card` varchar(512) NULL COMMENT '手持银行卡',
  `bank_card` varchar(512) NULL COMMENT '银行卡',
  `permit_bank_code` varchar(512) NULL COMMENT '开户许可证',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  `use_status` varchar(32) NULL COMMENT '使用状态',
  `deleted` bigint(20) NULL DEFAULT 0 COMMENT '是否删除',
  PRIMARY KEY (`id`),
  KEY `IDX_ACCOUNT_NO` (`account_no`),
  UNIQUE KEY `UK_MER_ACCOUNT_IDX` (`merchant_id`, `account_no`, `deleted`),
  UNIQUE KEY `UK_ORDER_NO_IDX` (`order_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4
;

CREATE TABLE `demeter_merchant_transfer` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `company_id` bigint(20) NOT NULL COMMENT '企业id',
  `transfer_no` varchar(68) NOT NULL COMMENT '转账no',
  `out_merchant_no` varchar(100) NOT NULL COMMENT '出款方商编',
  `out_merchant_id` bigint(20) NOT NULL COMMENT '出款方id',
  `out_merchant_name` varchar(50) NOT NULL COMMENT '出款方名字',
  `in_merchant_no` varchar(100) NOT NULL COMMENT '入款方商编',
  `in_merchant_id` bigint(20) NOT NULL COMMENT '入款方商户id',
  `in_merchant_name` varchar(50) NOT NULL COMMENT '入款方商户name',
  `amount` decimal(10,2) NOT NULL COMMENT '转账金额',
  `channel` varchar(50) NOT NULL COMMENT '渠道',
  `status` varchar(50) NOT NULL DEFAULT 'WAIT_CHECK' COMMENT '状态',
  `tran_failed_msg` varchar(255) NULL COMMENT '转账失败信息',
  `trans_tag` varchar(255) NOT NULL COMMENT '转账标签',
  `check_reject_reason` varchar(255) NULL COMMENT '拒绝理由',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `create_user_name` varchar(50) NOT NULL COMMENT '创建人name',
  `create_user_id` bigint(20) NOT NULL COMMENT '创建人id',
  `update_time` datetime NOT NULL COMMENT '更新时间',
  `update_user_name` varchar(50) NOT NULL COMMENT '更新人名字',
  `update_user_id` bigint(20) NOT NULL COMMENT '更新人id',
  `check_time` datetime NULL COMMENT '复核时间',
  `check_user_name` varchar(50) NULL COMMENT '复核人name',
  `check_user_id` bigint(20) NULL COMMENT '复核人id',
  `transfer_time` datetime NULL COMMENT '转账时间',
  `approval_number` varchar(68) NOT NULL COMMENT '申请单号',
  `biz_type` varchar(64) NOT NULL DEFAULT 'MANUAL_TRANS' COMMENT '业务类型',
  `allow_manual_operate` tinyint(1) NOT NULL DEFAULT 1 COMMENT '是否允许人工干预',
  `biz_no` varchar(64) NULL DEFAULT 'MANUAL_TRANSFER' COMMENT '业务单号',
  PRIMARY KEY (`id`),
  KEY `idx` (`company_id`, `transfer_no`),
  KEY `idx_merchant` (`out_merchant_no`, `in_merchant_no`),
  KEY `idx_trans_time` (`transfer_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4
;

CREATE TABLE `demeter_merchant_transfer_call_log` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `trans_id` bigint(20) NOT NULL,
  `user_id` bigint(20) NOT NULL,
  `user_name` varchar(50) NOT NULL,
  `oper_time` datetime NOT NULL,
  `ext_info` longtext NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4
;

CREATE TABLE `demeter_mq_fail_log` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `mq_type` varchar(50) NOT NULL COMMENT 'MQ类型',
  `content` text NULL COMMENT '消息内容',
  `handle` tinyint(1) NULL DEFAULT 0 COMMENT '是否处理',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4
;

CREATE TABLE `demeter_payment_advance_hj` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `out_apply_no` varchar(50) NOT NULL COMMENT '对应支付款表的外部付款申请号',
  `transfer_order_no` varchar(50) NOT NULL COMMENT '转账订单号',
