CREATE TABLE `demeter_payment_apply` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `serial_no` varchar(128) NOT NULL COMMENT '流水号',
  `status` varchar(32) NULL COMMENT '状态',
  `apply_type` varchar(32) NULL COMMENT '申请类型',
  `biz_apply_no` varchar(128) NOT NULL COMMENT '业务付款申请号',
  `biz_type` varchar(32) NOT NULL COMMENT '如:商城订单支付/订单尾款',
  `trade_type` varchar(128) NULL COMMENT '交易类型',
  `amount` decimal(10,2) NOT NULL COMMENT '付款金额',
  `is_split_success` tinyint(1) NULL COMMENT '是否分账成功',
  `is_zero_payment` tinyint(1) NULL COMMENT '是否0元支付',
  `apply_user_id` bigint(20) NULL COMMENT '申请人ID',
  `apply_user_name` varchar(64) NULL COMMENT '申请人名称',
  `apply_user_phone` varchar(32) NULL COMMENT '申请人电话',
  `company_id` bigint(20) NOT NULL,
  `ext_info` varchar(2000) NULL COMMENT '扩展信息',
  `payment_channel_type` varchar(20) NOT NULL DEFAULT 'HLB' COMMENT '支付渠道',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '最后修改时间',
  `sub_payment_channel_type` varchar(20) NOT NULL DEFAULT 'HLB' COMMENT '子支付渠道',
  `hl_finish_payment` tinyint(4) NOT NULL DEFAULT 0,
  `original_serial_no` varchar(128) NOT NULL DEFAULT '' COMMENT '流水号',
  PRIMARY KEY (`id`),
  KEY `NK_BIZ_NO_COMPANY_IDX` (`biz_apply_no`, `company_id`, `biz_type`),
  KEY `idx_company_id_serial_no_create_time` (`company_id`, `serial_no`, `create_time`),
  KEY `idx_create_time_company_id_serial_no` (`create_time`, `company_id`, `serial_no`),
  KEY `idx_original_serial_no` (`original_serial_no`),
  UNIQUE KEY `uk_serial_no` (`serial_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='付款申请'
;

