  `order_no` varchar(64) NULL COMMENT '订单号',
  `amount` decimal(12,2) NULL COMMENT '金额',
  `company_id` bigint(20) NULL COMMENT '企业ID',
  `payment_type` varchar(32) NULL COMMENT '支付方式',
  `create_time` datetime NULL COMMENT '最后修改时间',
  `settlement_type` varchar(32) NOT NULL DEFAULT 'DELIVERY_DATE' COMMENT '结算方式，DELIVERY_DATE：按供货日期结算，DEPOSIT：按照保证金结算',
  PRIMARY KEY (`id`),
  KEY `idx_accountitemid` (`split_account_item_id`),
  KEY `idx_orderno` (`order_no`),
  KEY `idx_serialno` (`payment_apply_serial_no`, `split_account_item_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='分账订单明细'
;

CREATE TABLE `demeter_payment_callback_log` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `app_id` varchar(30) NULL,
  `total_fee` int(11) NULL COMMENT '订单金额，单位分	',
  `transaction_id` varchar(50) NULL COMMENT '外部交易号',
  `out_trade_no` varchar(50) NULL COMMENT '商户订单号',
  `open_id` varchar(40) NULL,
  `attach` varchar(255) NULL COMMENT '商家数据包，原样返回',
  `callback_content` text NULL COMMENT '回调内容',
  `time_end` datetime NULL COMMENT '回调时间',
  `ret_code` varchar(20) NULL COMMENT '第三方返回状态',
  `callback_way` varchar(30) NULL COMMENT '支付：PAY,退款：REFUND',
  `create_time` datetime NULL COMMENT '创建时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_out_trade_no` (`out_trade_no`, `ret_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4
;

CREATE TABLE `demeter_payment_callback_log_hj` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `merchant_no` varchar(50) NOT NULL COMMENT '商户商编',
  `parent_merchant_no` varchar(20) NULL COMMENT '平台商户号',
  `out_trade_no` varchar(50) NOT NULL COMMENT '商户交易订单号',
  `amount` decimal(10,2) NOT NULL COMMENT '交易金额',
  `return_args` varchar(200) NULL COMMENT '回传参数',
  `status` varchar(10) NULL COMMENT '支付状态',
  `trx_no` varchar(50) NULL COMMENT '交易流水号',
  `callback_content` text NULL COMMENT '回调内容',
  `callback_way` varchar(30) NOT NULL COMMENT '回调方式',
  `pay_time` datetime NULL COMMENT '支付时间',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_out_trade_no` (`out_trade_no`, `status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='汇聚支付回调'
;

CREATE TABLE `demeter_payment_channel` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `payment_type_id` bigint(20) NULL,
