CREATE TABLE `demeter_payment_ea_transfer_hlb` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `merchant_id` bigint(20) NOT NULL COMMENT '商户id',
  `merchant_no` varchar(30) NOT NULL COMMENT '商户编号',
  `virtual_account_no` varchar(30) NOT NULL COMMENT '电子户账号',
  `batch_no` varchar(50) NOT NULL COMMENT '批次号',
  `transfer_type` varchar(20) NOT NULL COMMENT '电子户业务类型',
  `biz_no` varchar(32) NOT NULL COMMENT '上层业务单据号',
  `transfer_data` text NULL COMMENT '转账结果数据',
  `amount` decimal(10,2) NULL COMMENT '申请转账金额',
  `real_amount` decimal(10,2) NULL COMMENT '实际转账金额',
  `status` varchar(20) NULL COMMENT '批次状态',
  `deleted` bigint(20) NOT NULL COMMENT '是否删除',
