  UNIQUE KEY `UNIQUE_MERCHANT_ORDER_ID_IDX` (`merchant_no`, `order_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='电子户提现到合利宝详细记录'
;

CREATE TABLE `demeter_payment_log` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `pay_apply_serial_no` varchar(128) NOT NULL COMMENT '付款申请流水号',
  `biz_apply_no` varchar(128) NOT NULL COMMENT '业务付款申请号',
  `out_apply_no` varchar(128) NOT NULL COMMENT '外部付款申请号',
  `biz_type` varchar(32) NOT NULL COMMENT '如:商城订单支付/订单尾款',
  `mch_id` varchar(128) NOT NULL COMMENT '商户ID',
  `pay_type_id` bigint(20) NOT NULL COMMENT '支付方式ID',
  `pay_type_code` varchar(32) NOT NULL COMMENT '支付方式CODE',
  `pay_type_name` varchar(32) NOT NULL COMMENT '支付方式NAME',
  `pay_channel_id` bigint(20) NOT NULL COMMENT '支付渠道ID',
  `pay_channel_code` varchar(32) NOT NULL COMMENT '支付渠道CODE',
  `pay_channel_name` varchar(32) NOT NULL COMMENT '支付渠道NAME',
  `out_transaction_id` varchar(128) NULL COMMENT '外部交易号',
  `amount` decimal(10,2) NOT NULL COMMENT '金额',
  `status` varchar(32) NOT NULL COMMENT '支付状态',
