  `merchant_biz_type` varchar(50) NOT NULL COMMENT '业务类型',
  `transfer_status` varchar(50) NOT NULL COMMENT '转账状态',
  `out_account` varchar(50) NOT NULL COMMENT '出款帐户',
  `int_account` varchar(50) NOT NULL COMMENT '入款帐户',
