  `trx_no` varchar(50) NULL COMMENT '转账流水号',
  `transfer_remark` varchar(255) NULL COMMENT '转账说明',
  `operate_user_id` int(11) NOT NULL COMMENT '操作用户id',
  `operate_user_name` varchar(30) NOT NULL COMMENT '操作用户名',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `UK_MERCHANT_ORDER_NO` (`merchant_order_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='汇聚支付营销账户充值/提现表'
;

CREATE TABLE `demeter_payment_marketing_transfer_hlb` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `company_id` bigint(20) NOT NULL COMMENT '企业id',
  `merchant_no` varchar(50) NOT NULL COMMENT '平台商户号',
  `merchant_biz_type` varchar(64) NOT NULL COMMENT '账户业务类型，具体查看MerchantBizTypeItemEnum枚举',
  `transfer_status` varchar(50) NULL COMMENT '转账状态',
  `order_id` varchar(50) NULL COMMENT '商户订单号',
  `serial_number` varchar(50) NULL COMMENT '平台流水号',
  `amount` varchar(50) NULL COMMENT '转账金额',
  `reason` varchar(1024) NULL COMMENT '转账说明',
  `operate_user_id` int(11) NOT NULL COMMENT '操作用户id',
  `operate_user_name` varchar(30) NOT NULL COMMENT '操作用户名',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`),
