CREATE TABLE `demeter_payment_pay` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `pay_apply_serial_no` varchar(50) NOT NULL COMMENT '付款申请流水号',
  `biz_apply_no` varchar(50) NOT NULL COMMENT '业务付款申请号',
  `out_apply_no` varchar(50) NOT NULL COMMENT '外部付款申请号',
  `biz_type` varchar(32) NULL COMMENT '如:商城订单支付/订单尾款',
  `merchant_no` varchar(20) NOT NULL COMMENT '商户编号',
  `pay_type_id` int(11) NOT NULL COMMENT '支付方式ID',
  `pay_type_code` varchar(32) NOT NULL COMMENT '支付方式CODE，WX_PAY：微信支付，VIRTUAL_PAY：虚拟支付',
  `pay_type_name` varchar(32) NOT NULL COMMENT '支付方式NAME',
  `out_transaction_id` varchar(50) NULL COMMENT '外部交易流水号',
  `trade_type` varchar(64) NULL COMMENT '交易类型描述',
  `company_id` bigint(20) NOT NULL COMMENT '企业ID',
  `amount` decimal(10,2) NOT NULL COMMENT '金额',
  `status` varchar(32) NOT NULL COMMENT '支付状态',
  `pay_time` datetime NULL COMMENT '支付时间',
  `prepay_id` varchar(64) NULL COMMENT '预支付ID',
  `ret_code` varchar(20) NULL COMMENT '第三方支付返回状态码',
  `ret_msg` varchar(100) NULL COMMENT '第三方支付返回信息',
  `ret_status` varchar(20) NULL COMMENT '第三方支付状态',
  `spilt_bill_rule` text NULL COMMENT '分账规则Json串',
  `attach` varchar(255) NULL COMMENT '附加信息',
  `payment_channel_type` varchar(20) NOT NULL DEFAULT 'HLB_PAY' COMMENT '支付渠道',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '最后修改时间',
  PRIMARY KEY (`id`),
  KEY `idx_biz_apply_no` (`biz_apply_no`),
  KEY `idx_pay_apply_serial_no` (`pay_apply_serial_no`),
  UNIQUE KEY `uk_out_apply_no` (`out_apply_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='支付日志'
;

CREATE TABLE `demeter_payment_pay22` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `pay_apply_serial_no` varchar(50) NOT NULL COMMENT '付款申请流水号',
  `biz_apply_no` varchar(50) NOT NULL COMMENT '业务付款申请号',
  `out_apply_no` varchar(50) NOT NULL COMMENT '外部付款申请号',
  `biz_type` varchar(32) NULL COMMENT '如:商城订单支付/订单尾款',
  `merchant_no` varchar(20) NOT NULL COMMENT '商户编号',
  `pay_type_id` int(11) NOT NULL COMMENT '支付方式ID',
  `pay_type_code` varchar(32) NOT NULL COMMENT '支付方式CODE，WX_PAY：微信支付，VIRTUAL_PAY：虚拟支付',
  `pay_type_name` varchar(32) NOT NULL COMMENT '支付方式NAME',
  `out_transaction_id` varchar(50) NULL COMMENT '外部交易流水号',
  `trade_type` varchar(64) NULL COMMENT '交易类型描述',
  `company_id` bigint(20) NOT NULL COMMENT '企业ID',
  `amount` decimal(10,2) NOT NULL COMMENT '金额',
  `status` varchar(32) NOT NULL COMMENT '支付状态',
  `pay_time` datetime NULL COMMENT '支付时间',
  `prepay_id` varchar(64) NULL COMMENT '预支付ID',
  `ret_code` varchar(20) NULL COMMENT '第三方支付返回状态码',
  `ret_msg` varchar(100) NULL COMMENT '第三方支付返回信息',
  `ret_status` varchar(20) NULL COMMENT '第三方支付状态',
  `spilt_bill_rule` text NULL COMMENT '分账规则Json串',
  `attach` varchar(255) NULL COMMENT '附加信息',
  `payment_channel_type` varchar(20) NOT NULL DEFAULT 'HLB_PAY' COMMENT '支付渠道',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '最后修改时间',
  PRIMARY KEY (`id`),
  KEY `idx_biz_apply_no` (`biz_apply_no`),
  KEY `idx_pay_apply_serial_no` (`pay_apply_serial_no`),
  UNIQUE KEY `uk_out_apply_no` (`out_apply_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='支付日志'
;

CREATE TABLE `demeter_payment_pay_ob` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `payment_pay_id` bigint(20) NOT NULL COMMENT 'payment_pay主键ID',
  `bank_id` varchar(20) NOT NULL COMMENT '银行卡编码',
  `business` varchar(20) NOT NULL COMMENT '业务类型, B2C:  个人支付,  B2B: 企业支付',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_payment_pay_id` (`payment_pay_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='网银支付记录'
;

CREATE TABLE `demeter_payment_refund` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `out_pay_apply_no` varchar(50) NOT NULL COMMENT '外部付款申请号(一笔退款必须对应一笔支付)',
  `biz_refund_apply_no` varchar(50) NOT NULL COMMENT '业务退款单号',
  `out_refund_apply_no` varchar(50) NOT NULL COMMENT '外部退款申请号',
  `refund_apply_serial_no` varchar(50) NOT NULL COMMENT '退款申请流水号',
  `pay_apply_serial_no` varchar(50) NOT NULL COMMENT '付款流水号',
  `amount` decimal(10,2) NOT NULL COMMENT '退款金额',
  `status` varchar(32) NOT NULL COMMENT '退款状态',
  `ret_code` varchar(10) NULL COMMENT '第三方退款返回码',
  `ret_msg` varchar(255) NULL COMMENT '三方同步返回错误',
  `out_transaction_id` varchar(50) NULL COMMENT '外部交易流水号',
  `ret_status` varchar(10) NULL COMMENT '第三方支付状态',
  `refund_rule` text NULL COMMENT '退款规则json字符串',
  `refund_way` varchar(20) NOT NULL COMMENT 'WX_PAY：微信退款，VIRTUAL_PAY：虚拟退款',
  `company_id` bigint(20) NOT NULL COMMENT '企业ID',
  `attach` varchar(255) NULL COMMENT '附件信息',
  `merchant_no` varchar(20) NULL COMMENT '商户ID',
  `refund_reason` varchar(255) NULL,
  `payment_channel_type` varchar(20) NOT NULL DEFAULT 'HLB_REFUND' COMMENT '支付渠道',
  `refund_time` datetime NULL COMMENT '退款时间',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '最后修改时间',
  PRIMARY KEY (`id`),
  KEY `idx_biz_refund_apply_no` (`biz_refund_apply_no`),
  KEY `idx_out_pay_apply_no` (`out_pay_apply_no`),
  KEY `idx_pay_apply_serial_no` (`pay_apply_serial_no`),
  KEY `idx_pay_serial_no_refund` (`pay_apply_serial_no`, `refund_way`),
  UNIQUE KEY `idx_refund_apply_no` (`out_refund_apply_no`),
  KEY `idx_refund_apply_serial_no` (`refund_apply_serial_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='支付退款日志'
;

