;

CREATE TABLE `demeter_payment_split_bill_log` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `out_apply_no` varchar(50) NULL COMMENT '外部付款申请号',
  `split_bill_amount` decimal(10,2) NULL COMMENT '分账金额',
  `split_bill_merchant_email` varchar(50) NULL COMMENT '分账邮箱',
  `split_bill_status` varchar(15) NULL COMMENT '分账状态，成功：SUCCESS，失败：FAILED',
  `split_Bill_order_num` varchar(50) NULL COMMENT '分账订单号',
  `create_time` datetime NULL COMMENT '创建时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4
;

CREATE TABLE `demeter_payment_split_fail_record` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `payment_apply_serial_no` varchar(64) NULL COMMENT '支付流水号',
  `payment_channel_type` varchar(32) NULL COMMENT '支付通道, HJ, HLB',
  `merchant_no` varchar(30) NOT NULL COMMENT '商户编号',
  `merchant_status` varchar(30) NOT NULL COMMENT '商户状态',
  `account_status` varchar(30) NOT NULL COMMENT '账户状态',
  `payment_type` varchar(30) NOT NULL COMMENT '支付类型',
  `deleted` tinyint(1) NOT NULL DEFAULT 0 COMMENT '删除',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='合利宝分账失败记录表'
;

CREATE TABLE `demeter_payment_transfer` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `transfer_order_no` varchar(64) NOT NULL COMMENT '转账订单单号',
  `transfer_merchant_no` varchar(32) NOT NULL COMMENT '转账商户号',
  `transfer_merchant_id` bigint(20) NULL COMMENT '转账商户主键ID',
  `collection_merchant_no` varchar(32) NOT NULL COMMENT '收款商户号',
  `collection_merchant_id` bigint(20) NOT NULL COMMENT '收款商户ID',
  `transfer_amount` decimal(10,2) NOT NULL COMMENT '转账金额',
  `status` varchar(32) NOT NULL COMMENT '处理状态',
  `serial_number` varchar(64) NULL COMMENT '合利宝平台流水号',
  `order_number` varchar(64) NOT NULL COMMENT '订单号',
  `trade_type` varchar(64) NOT NULL COMMENT '交易类型',
  `transfer_type` varchar(64) NOT NULL DEFAULT 'ACCOUNT_TO_PLATFORM' COMMENT '转账类型',
  `company_id` bigint(20) NOT NULL COMMENT '企业ID',
  `statement_date` date NOT NULL COMMENT '订单归属日期',
  `settlement_date` date NULL COMMENT '结算时间',
  `operation_user_id` bigint(20) NOT NULL COMMENT '操作人',
  `operation_user_name` varchar(32) NOT NULL COMMENT '操作人姓名',
  `fail_reason` varchar(255) NULL COMMENT '失败原因',
  `payment_channel_type` varchar(30) NOT NULL DEFAULT 'HLB' COMMENT '支付渠道',
  `deleted` bigint(20) NOT NULL DEFAULT 0 COMMENT '是否删除，非0代表已删除',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '修改时间',
  `settlement_type` varchar(32) NOT NULL DEFAULT 'DELIVERY_DATE' COMMENT '结算方式，DELIVERY_DATE：按供货日期结算，DEPOSIT：按照保证金结算',
  `ext_info` varchar(4096) NULL COMMENT '扩展字段，用于存储业务特定信息',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_transfer_order_no` (`transfer_order_no`, `deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4
;

CREATE TABLE `demeter_payment_transfer_callback_log_hlb` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `merchant_no` varchar(30) NOT NULL COMMENT '商户编号',
  `order_id` varchar(50) NOT NULL COMMENT '订单号',
  `status` varchar(20) NULL COMMENT '订单状态',
  `callback_content` text NULL COMMENT '回调内容',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='合利宝代付回调记录表'
;

CREATE TABLE `demeter_payment_transfer_callback_log_hlb_bak` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `merchant_no` varchar(30) NOT NULL COMMENT '商户编号',
  `order_id` varchar(50) NOT NULL COMMENT '订单号',
  `status` varchar(20) NULL COMMENT '订单状态',
  `callback_content` text NULL COMMENT '回调内容',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='合利宝代付回调记录表'
;

CREATE TABLE `demeter_payment_transfer_hlb` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `merchant_id` bigint(20) NOT NULL COMMENT '商户ID',
  `merchant_no` varchar(30) NOT NULL COMMENT '商户编号',
  `sign_name` varchar(64) NULL COMMENT '商户签约名',
  `balance` varchar(20) NULL COMMENT '账户余额',
  `total_amount` varchar(20) NULL COMMENT '待转账金额',
  `status` tinyint(4) NOT NULL DEFAULT 0 COMMENT '是否已结算, 0:未转账, 1:已转账',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`)
