;

CREATE TABLE `demeter_payment_transfer_hlb_bak` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `merchant_id` bigint(20) NOT NULL COMMENT '商户ID',
  `merchant_no` varchar(30) NOT NULL COMMENT '商户编号',
  `sign_name` varchar(64) NULL COMMENT '商户签约名',
  `balance` varchar(20) NULL COMMENT '账户余额',
  `total_amount` varchar(20) NULL COMMENT '待转账金额',
  `status` tinyint(4) NOT NULL DEFAULT 0 COMMENT '是否已结算, 0:未转账, 1:已转账',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='代付数据汇总表'
;

CREATE TABLE `demeter_payment_transfer_record_hlb` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `merchant_no` varchar(30) NOT NULL COMMENT '商户编号',
  `bank_code` varchar(20) NOT NULL COMMENT '商户签约名',
  `bank_account_no` varchar(32) NOT NULL COMMENT '银行账号',
  `bank_account_name` varchar(32) NOT NULL COMMENT '银行账户名',
  `bank_union_code` varchar(32) NULL COMMENT '联行号, 对公联行号必填',
  `biz_type` varchar(10) NOT NULL COMMENT '业务类型, B2B:对公, B2C:对私',
  `fee_type` varchar(20) NOT NULL COMMENT '手续费收取方, PAYER:付款方收取手续费, RECEIVER:收款方收取手续费',
  `summary` varchar(32) NULL COMMENT '备注',
  `order_id` varchar(50) NOT NULL COMMENT '订单号',
  `serial_number` varchar(50) NULL COMMENT '平台流水号',
  `order_status` varchar(20) NULL COMMENT '订单状态',
  `notify_type` varchar(20) NULL COMMENT '通知类型, ORDER_STATUS:普通通知, RETURN_REMITTANCE:退汇通知（交易成功后的通知失败）',
  `reason` varchar(128) NULL COMMENT '成功或失败原因',
  `create_date` varchar(32) NULL COMMENT '合利宝订单创建时间',
  `complete_date` varchar(32) NULL COMMENT '合利宝订单创建时间',
  `amount` varchar(20) NOT NULL COMMENT '订单金额',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `UNIQUE_MERCHANT_ORDER_ID_IDX` (`merchant_no`, `order_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='合利宝代付记录'
;

