) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='合利宝代付记录'
;

CREATE TABLE `demeter_payment_transfer_source_record` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `merchant_id` bigint(20) NOT NULL COMMENT '商户ID',
  `merchant_no` varchar(30) NOT NULL COMMENT '商户编号',
  `sign_name` varchar(64) NULL COMMENT '商户签约名',
  `company_id` bigint(20) NOT NULL COMMENT '企业ID',
  `operation_type` varchar(10) NOT NULL COMMENT '操作类型，SPLIT_BILL：分账，SETTLEMENT：结算',
  `trade_amount` decimal(10,2) NULL COMMENT '交易金额',
  `trade_desc` varchar(50) NULL COMMENT '交易描述',
  `income_expenditure` varchar(10) NULL COMMENT '收入/支出，对于结算来说是支出',
  `payment_channel_type` varchar(32) NULL COMMENT '支付方式CODE，WX_PAY：微信支付，VIRTUAL_PAY：虚拟支付，手动提现为空',
  `order_number` varchar(64) NULL COMMENT '订单号',
  `payment_apply_serial_no` varchar(64) NULL COMMENT '支付流水号',
  `trade_type` varchar(64) NULL COMMENT '交易类型',
  `settlement` varchar(30) NOT NULL COMMENT '是否结算，SETTLED：已结算，PENDING_SETTLEMENT：待结算',
  `split_bill_success` varchar(10) NOT NULL COMMENT '分账是否成功，SUCCESS：成功，FAILED：失败',
  `statement_date` datetime NULL COMMENT '归属日期',
  `settlement_date` datetime NULL COMMENT '结算日期',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='合利宝代付功能原始数据'
;

CREATE TABLE `demeter_payment_type` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `payment_type_code` varchar(64) NULL,
  `payment_type_name` varchar(64) NULL COMMENT '微信/支付宝/银联',
  `current_payment_channel_id` bigint(20) NULL COMMENT '当前支付渠道id',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='支付方式'
;

CREATE TABLE `demeter_payment_violation_apply` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `serial_no` varchar(50) NOT NULL COMMENT '流水号',
  `status` varchar(32) NOT NULL COMMENT '支付状态',
  `biz_apply_no` varchar(50) NOT NULL COMMENT '内部支付申请号',
  `out_apply_no` varchar(50) NULL COMMENT '外部支付申请号，线下支付该字段为空',
  `trade_type` varchar(32) NOT NULL COMMENT '交易类型',
  `apply_user_id` bigint(20) NOT NULL COMMENT '申请人ID',
  `amount` decimal(10,2) NOT NULL COMMENT '请求金额',
  `payment_way` varchar(32) NOT NULL COMMENT '支付方式，WX_PAY：微信付款，OFFLINE_PAY：线下付款',
  `payment_channel_type` varchar(20) NOT NULL DEFAULT 'HJ' COMMENT '支付渠道',
  `company_id` bigint(20) NOT NULL COMMENT '企业ID',
  `payment_type` varchar(32) NOT NULL DEFAULT 'PAY' COMMENT '支付类型, PAY：付款，REFUND：退款',
  `create_time` datetime NOT NULL COMMENT '申请时间',
  `update_time` datetime NOT NULL COMMENT '更新时间/支付时间',
  PRIMARY KEY (`id`),
  KEY `idx_biz_apply_no` (`biz_apply_no`),
  KEY `idx_date_status` (`company_id`, `create_time`),
  UNIQUE KEY `idx_out_apply_no` (`out_apply_no`),
  KEY `idx_serial_no` (`serial_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='违规申请'
;

CREATE TABLE `demeter_payment_violation_callback_log_hj` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `merchant_no` varchar(50) NOT NULL COMMENT '商户商编',
  `out_trade_no` varchar(50) NOT NULL COMMENT '商户交易订单号',
  `amount` decimal(10,2) NOT NULL COMMENT '交易金额',
  `return_args` varchar(200) NULL COMMENT '回传参数',
  `status` varchar(10) NULL COMMENT '支付状态',
  `trx_no` varchar(50) NULL COMMENT '交易流水号',
  `callback_content` text NULL COMMENT '回调内容',
  `callback_way` varchar(30) NOT NULL COMMENT '回调方式',
  `pay_time` datetime NULL COMMENT '支付时间',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_out_trade_no` (`out_trade_no`, `status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='汇聚支付回调'
;

CREATE TABLE `demeter_payment_violation_pay` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `pay_apply_serial_no` varchar(50) NOT NULL COMMENT '付款申请流水号',
  `biz_apply_no` varchar(50) NOT NULL COMMENT '业务付款申请号',
  `out_apply_no` varchar(50) NOT NULL COMMENT '外部付款申请号',
  `out_transaction_id` varchar(50) NULL COMMENT '外部交易流水号',
  `trade_type` varchar(64) NULL COMMENT '交易类型描述',
  `company_id` bigint(20) NOT NULL COMMENT '企业ID',
  `amount` decimal(10,2) NOT NULL COMMENT '金额',
  `status` varchar(32) NOT NULL COMMENT '支付状态',
  `pay_time` datetime NULL COMMENT '支付时间',
  `prepay_id` varchar(64) NULL COMMENT '预支付ID',
  `ret_code` varchar(20) NULL COMMENT '第三方支付返回状态码',
  `ret_msg` varchar(100) NULL COMMENT '第三方支付状态',
  `ret_status` varchar(20) NULL COMMENT '第三方支付状态',
  `payment_channel_type` varchar(20) NOT NULL DEFAULT 'HJ' COMMENT '支付渠道',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '最后修改时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_out_apply_no` (`out_apply_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='违规支付日志'
;

CREATE TABLE `demeter_pickup_fee_bill` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `bill_no` varchar(32) NOT NULL COMMENT '账单编号，格式CS+YYYYMMDD+6位序列，全局唯一',
  `company_id` bigint(20) NOT NULL COMMENT '企业ID',
  `seller_id` bigint(20) NOT NULL COMMENT '商家ID',
  `seller_name` varchar(256) NULL COMMENT '商家名称（冗余）',
  `fleet_code` varchar(32) NOT NULL COMMENT '车队编码',
  `fleet_name` varchar(128) NULL COMMENT '车队名称（冗余）',
  `goods_id` bigint(20) NOT NULL COMMENT '商品ID',
  `goods_name` varchar(256) NULL COMMENT '商品名称（冗余）',
  `purchase_type` varchar(32) NOT NULL COMMENT '揽收类型：PREDICTION/TEMP/PROACTIVE/RETURN',
  `qty` decimal(18,4) NOT NULL COMMENT '计费件数（该账单维度汇总的件数）',
  `unit_price` decimal(10,2) NOT NULL COMMENT '件单价(元/件)，按商品件标准重量所属阶梯取价',
  `pre_amount` decimal(18,2) NOT NULL COMMENT '折扣前采师费(元)=件数×件单价',
  `discount_rate` decimal(5,2) NOT NULL DEFAULT 100.00 COMMENT '优惠折扣(%)，如85表示85折；不享折扣为100（即原价）',
  `discount_amount` decimal(18,2) NOT NULL DEFAULT 0.00 COMMENT '优惠金额(元)',
  `payable_amount` decimal(18,2) NOT NULL COMMENT '应付采师费(元)=应付×折扣（不享折扣=应付）',
  `platform_split_rate` decimal(5,2) NOT NULL COMMENT '平台抽佣率(%)，快照自车队配置',
  `statement_date` date NOT NULL COMMENT '揽收日期',
  `bill_date` date NOT NULL COMMENT '账单日期（日终计算生成日）',
  `rule_template_id` bigint(20) NULL COMMENT '计费规则模板ID（快照）',
  `rule_template_name` varchar(50) NULL COMMENT '计费规则模板名称（快照）',
  `pay_status` varchar(32) NOT NULL DEFAULT 'PENDING_CONFIRM' COMMENT '支付状态：PENDING_CONFIRM=待确认，PENDING_PAY=待支付，PAYING=支付中，PAID=已支付，VOID=已作废',
  `pay_time` datetime NULL COMMENT '支付时间',
  `payment_no` varchar(64) NULL COMMENT '当前支付申请单号',
  `create_user_id` bigint(20) NULL COMMENT '创建人ID（系统生成，0表示Job）',
  `create_user_name` varchar(64) NULL COMMENT '创建人姓名（系统生成时为系统）',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_user_id` bigint(20) NULL COMMENT '更新人ID',
  `update_user_name` varchar(64) NULL COMMENT '更新人姓名',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bigint(20) NOT NULL DEFAULT 0 COMMENT '是否删除 0正常 非0删除',
  PRIMARY KEY (`id`),
  KEY `idx_payment_no` (`payment_no`),
  UNIQUE KEY `nk_bill_dimension` (`company_id`, `seller_id`, `fleet_code`, `goods_id`, `purchase_type`, `statement_date`, `deleted`),
  KEY `nk_company_fleet_statement` (`company_id`, `fleet_code`, `statement_date`, `deleted`, `id`),
  KEY `nk_fleet` (`fleet_code`),
  KEY `nk_pay_status` (`pay_status`),
  KEY `nk_seller_date` (`seller_id`, `statement_date`),
  UNIQUE KEY `uk_bill_no` (`bill_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='采师费账单：按商家+车队+货号+揽收类型维度生成，记录应付/实付/抽佣'
;

CREATE TABLE `demeter_pickup_fee_collect_detail` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `company_id` bigint(20) NOT NULL COMMENT '企业ID',
  `data_source_system` varchar(255) NULL COMMENT '数据来源(或归属)系统. tms|oms',
  `source_record_id` varchar(255) NULL COMMENT '源记录ID。tms:销售揽收=wms_base_task.id；退货揽收=导入批次内行ID; oms：---',
  `statement_date` date NOT NULL COMMENT '归属/揽收日期，用于日终计算按日归集',
  `stock_no` varchar(64) NULL COMMENT '仓库编码',
  `stock_name` varchar(128) NULL COMMENT '仓库名称（冗余）',
  `fleet_code` varchar(32) NULL COMMENT '车队编码，来源tms.tms_fleet.fleet_code',
  `fleet_name` varchar(128) NULL COMMENT '车队名称（冗余）',
  `picker_user_id` bigint(20) NULL COMMENT '采师ID',
  `picker_user_name` varchar(64) NULL COMMENT '采师姓名（冗余）',
  `seller_id` bigint(20) NULL COMMENT '商家ID',
  `seller_name` varchar(256) NULL COMMENT '商家名称（冗余）',
  `goods_id` bigint(20) NOT NULL COMMENT '商品ID；计费按此归集',
  `goods_name` varchar(256) NULL COMMENT '商品名称（冗余）',
  `picker_phone` varchar(20) NULL COMMENT '采师联系电话；退货导入重复校验使用',
  `collect_qty` decimal(18,4) NOT NULL DEFAULT 0.0000 COMMENT '揽收件数：销售揽收=preNumber（预计/揽收数量）；退货揽收=导入的揽收件数（退货计费依据）',
  `receive_qty` decimal(18,4) NOT NULL DEFAULT 0.0000 COMMENT '收货数量：销售揽收=receiveNumber（仓库打标收货数量，销售计费依据）；退货揽收为0',
  `gross_weight` decimal(18,4) NOT NULL DEFAULT 0.0000 COMMENT '单件毛重(kg)',
  `receive_total_gross_weight` decimal(18,4) NOT NULL DEFAULT 0.0000 COMMENT '收货总毛重(kg)=receive_number×gross_weight（按此口径计算存储，计费不用，备对账）',
  `return_qty` decimal(18,4) NOT NULL DEFAULT 0.0000 COMMENT '退货件数：退货导入的退货件数（用于展示差异=退货件数-揽收件数）；销售揽收为0',
  `assign_time` datetime NULL COMMENT '分配时间（销售揽收调度时间）',
  `collect_time` datetime NULL COMMENT '揽收时间',
  `receive_time` datetime NULL COMMENT '收货时间（仓库打标时间）',
  `confirm_receive_time` datetime NULL COMMENT '确认收货时间',
  `source_create_time` datetime NULL COMMENT '源记录创建时间',
  `status` varchar(32) NULL COMMENT '源任务状态',
  `collect_type` varchar(16) NOT NULL COMMENT '揽收类型：SALES=销售揽收，RETURN=退货揽收',
  `purchase_type` varchar(32) NOT NULL COMMENT '采购类型：PREDICTION=预采，TEMP=临采，PROACTIVE=自主提报，RETURN=退货',
  `data_source` varchar(16) NOT NULL COMMENT '数据来源：SYNC=从tms同步（销售揽收），IMPORT=人工导入（退货揽收）',
  `record_status` varchar(16) NOT NULL DEFAULT 'VALID' COMMENT '记录状态：VALID=有效，VOID=作废；退货导入作废后置VOID，不参与计费/统计/导出',
  `void_reason` varchar(200) NULL COMMENT '作废原因（退货导入作废时填写）',
  `void_time` datetime NULL COMMENT '作废时间',
  `void_user_id` bigint(20) NULL COMMENT '作废操作人ID',
  `sync_batch_no` varchar(32) NULL COMMENT '同步批次号（销售揽收同步Job的批次，用于幂等与排查）',
  `billed` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已计费：0=否，1=是；日终计算后置1',
  `bill_id` varchar(32) NULL COMMENT '关联账单编号（计费后回写）',
  `create_user_id` bigint(20) NULL COMMENT '创建人ID（销售同步=系统/0；退货导入=导入操作人ID）',
  `create_user_name` varchar(64) NULL COMMENT '创建人姓名（销售同步=系统；退货导入=导入操作人）',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_user_id` bigint(20) NULL COMMENT '更新人ID',
  `update_user_name` varchar(64) NULL COMMENT '更新人姓名',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bigint(20) NOT NULL DEFAULT 0 COMMENT '是否删除 0正常 非0删除',
  PRIMARY KEY (`id`),
  KEY `nk_company_billing` (`company_id`, `billed`, `record_status`, `statement_date`, `deleted`),
  KEY `nk_company_statement` (`company_id`, `statement_date`),
  KEY `nk_fleet_code` (`fleet_code`),
  KEY `nk_picker_user_id` (`picker_user_id`),
  KEY `nk_return_duplicate` (`company_id`, `collect_type`, `data_source`, `record_status`, `seller_id`, `goods_id`, `statement_date`, `picker_user_id`, `picker_phone`, `deleted`),
  KEY `nk_return_query` (`collect_type`, `data_source`, `record_status`),
  UNIQUE KEY `uk_company_source_record_type` (`company_id`, `data_source_system`, `source_record_id`, `collect_type`, `deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='采师费揽收明细快照：销售揽收(SYNC)与退货揽收(IMPORT)统一存储于此表，用collect_type+data_source区分'
;

CREATE TABLE `demeter_pickup_fee_payment` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `payment_no` varchar(64) NOT NULL COMMENT '内部付款申请号，全局唯一，同时作为中信BUSS_ID',
  `buss_sub_id` varchar(64) NOT NULL COMMENT '中信业务子订单号，同一支付生命周期内保持不变',
  `idempotency_key` varchar(64) NOT NULL COMMENT '商家、车队和排序后账单ID集合生成的服务端幂等摘要',
  `company_id` bigint(20) NOT NULL COMMENT '企业ID',
  `seller_id` bigint(20) NOT NULL COMMENT '商家ID',
  `seller_company_id` bigint(20) NOT NULL COMMENT '商家企业ID，用于定位付款Merchant',
  `fleet_code` varchar(32) NOT NULL COMMENT '车队编码，同一支付单只能包含同一车队账单',
  `payer_merchant_id` bigint(20) NOT NULL COMMENT '商家付款Merchant ID快照',
  `payer_merchant_no` varchar(64) NOT NULL COMMENT '商家付款中信商户号快照',
  `payer_merchant_name` varchar(256) NOT NULL COMMENT '商家付款中信签约名称快照',
  `fleet_merchant_id` bigint(20) NOT NULL COMMENT '车队收款Merchant ID快照',
  `fleet_merchant_no` varchar(64) NOT NULL COMMENT '车队收款中信商户号快照',
  `fleet_merchant_name` varchar(256) NOT NULL COMMENT '车队收款中信签约名称快照',
  `platform_merchant_id` bigint(20) NOT NULL COMMENT '平台物流Merchant ID快照',
  `platform_merchant_no` varchar(64) NOT NULL COMMENT '平台物流中信商户号快照',
  `platform_merchant_name` varchar(256) NOT NULL COMMENT '平台物流中信签约名称快照',
  `total_amount` decimal(18,2) NOT NULL COMMENT '商家支付总金额，对应中信TRANS_AMT',
  `fleet_amount` decimal(18,2) NOT NULL COMMENT '车队收款金额，对应中信USER_C_AMT',
  `platform_amount` decimal(18,2) NOT NULL COMMENT '平台佣金金额，对应中信USER_SHARE_AMT1',
  `platform_split_rate` decimal(5,2) NOT NULL COMMENT '平台分润比例快照，按百分比保存',
  `channel` varchar(16) NOT NULL COMMENT '支付渠道，暂时固定:CITIC',
  `status` varchar(32) NOT NULL COMMENT '支付状态：PROCESSING=支付中，SUCCESS=成功，FAILED=失败，UNKNOWN=结果未知',
  `transfer_attempt_count` int(11) NOT NULL DEFAULT 0 COMMENT '已发起中信转账请求次数，首次加三次重试最大为4',
  `success_request_id` bigint(20) NULL COMMENT '最终成功的中信转账请求记录ID',
  `bank_user_ssn` varchar(64) NULL COMMENT '中信侧最终交易流水号',
  `pay_time` datetime NULL COMMENT '支付完成时间',
  `fail_code` varchar(64) NULL COMMENT '最终失败码',
  `fail_message` varchar(512) NULL COMMENT '最终失败原因',
  `ledger_posted` tinyint(1) NOT NULL DEFAULT 0 COMMENT '三方BillPro是否已完整入账：0=否，1=是',
  `create_user_id` bigint(20) NULL COMMENT '创建人ID',
  `create_user_name` varchar(64) NULL COMMENT '创建人姓名',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_user_id` bigint(20) NULL COMMENT '更新人ID',
  `update_user_name` varchar(64) NULL COMMENT '更新人姓名',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bigint(20) NOT NULL DEFAULT 0 COMMENT '是否删除，0正常，非0为被删除行ID',
  PRIMARY KEY (`id`),
  KEY `nk_company_time` (`company_id`, `deleted`, `create_time`),
  KEY `nk_fleet_time` (`company_id`, `fleet_code`, `deleted`, `create_time`),
  KEY `nk_idempotency` (`seller_id`, `idempotency_key`, `status`, `deleted`),
  KEY `nk_ledger_posted` (`ledger_posted`, `deleted`, `id`),
  KEY `nk_seller_status` (`seller_id`, `status`, `deleted`, `create_time`),
  UNIQUE KEY `uk_payment_no` (`payment_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='采师费业务支付单：保存商家付款、车队收款、平台佣金和支付终态快照'
;

CREATE TABLE `demeter_pickup_fee_payment_bill` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `payment_id` bigint(20) NOT NULL COMMENT '采师费支付单ID，关联demeter_pickup_fee_payment.id',
  `payment_no` varchar(64) NOT NULL COMMENT '内部付款申请号快照',
  `bill_id` bigint(20) NOT NULL COMMENT '一期采师费账单ID，关联demeter_pickup_fee_bill.id',
  `bill_no` varchar(32) NOT NULL COMMENT '一期采师费账单号快照',
  `payable_amount` decimal(18,2) NOT NULL COMMENT '账单应付金额快照',
  `statement_date` date NULL COMMENT '账单归属或揽收日期快照，异常账单允许为空',
  `create_user_id` bigint(20) NULL COMMENT '创建人ID',
  `create_user_name` varchar(64) NULL COMMENT '创建人姓名',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_user_id` bigint(20) NULL COMMENT '更新人ID',
  `update_user_name` varchar(64) NULL COMMENT '更新人姓名',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bigint(20) NOT NULL DEFAULT 0 COMMENT '是否删除，0正常，非0为被删除行ID',
  PRIMARY KEY (`id`),
  KEY `nk_bill_id` (`bill_id`, `deleted`, `id`),
  KEY `nk_bill_no` (`bill_no`, `deleted`),
  UNIQUE KEY `uk_payment_bill` (`payment_id`, `bill_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='采师费支付单与一期账单的历史关联和金额快照'
;

CREATE TABLE `demeter_pickup_fee_rule_exclude_category` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `template_id` bigint(20) NOT NULL COMMENT '所属规则模板ID，关联demeter_pickup_fee_rule_template.id',
  `category_id` bigint(20) NOT NULL COMMENT '排除类目ID（商品档案类目ID）；该类目下商品行即使达标也按原价计费，不享折扣',
  `category_name` varchar(128) NULL COMMENT '排除类目名称（冗余字段，便于列表展示与导入校验，避免每次join商品档案）',
  `category_level` tinyint(4) NULL COMMENT '类目等级（1=一级类目, 2=二级类目, ...）',
  `create_user_id` bigint(20) NULL COMMENT '创建人ID（本次维护该排除清单的操作人）',
  `create_user_name` varchar(64) NULL COMMENT '创建人姓名',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_user_id` bigint(20) NULL COMMENT '更新人ID',
  `update_user_name` varchar(64) NULL COMMENT '更新人姓名',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bigint(20) NOT NULL DEFAULT 0 COMMENT '是否删除 0正常 非0删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_template_cat` (`template_id`, `category_id`, `deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='不享受折扣类目清单：全量替换维护，达标折扣判定时该类目商品行按原价计费'
;

CREATE TABLE `demeter_pickup_fee_rule_exclude_seller` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `template_id` bigint(20) NOT NULL COMMENT '所属规则模板ID，关联demeter_pickup_fee_rule_template.id',
  `seller_id` bigint(20) NOT NULL COMMENT '排除商家ID；该商家所有商品行即使达标也按原价计费，不享折扣',
  `seller_name` varchar(256) NULL COMMENT '排除商家名称（冗余字段，便于列表展示与导入校验）',
  `create_user_id` bigint(20) NULL COMMENT '创建人ID（本次维护该排除清单的操作人）',
  `create_user_name` varchar(64) NULL COMMENT '创建人姓名',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_user_id` bigint(20) NULL COMMENT '更新人ID',
  `update_user_name` varchar(64) NULL COMMENT '更新人姓名',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bigint(20) NOT NULL DEFAULT 0 COMMENT '是否删除 0正常 非0删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_template_seller` (`template_id`, `seller_id`, `deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='不享受折扣商家清单：全量替换维护，达标折扣判定时该商家所有商品行按原价计费'
;

CREATE TABLE `demeter_pickup_fee_rule_ladder` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `template_id` bigint(20) NOT NULL COMMENT '所属规则模板ID，关联demeter_pickup_fee_rule_template.id',
  `min_weight` decimal(18,2) NOT NULL COMMENT '件标准重量区间下限(kg)，左开区间，即 (min_weight, max_weight]',
  `max_weight` decimal(18,2) NOT NULL COMMENT '件标准重量区间上限(kg)，右闭区间，即 (min_weight, max_weight]',
  `charge_mode` varchar(16) NOT NULL DEFAULT 'PER_PIECE' COMMENT '该阶梯结算方式：PER_PIECE=按件结算（一期仅支持按件）',
  `unit_price` decimal(18,2) NOT NULL COMMENT '该阶梯件单价(元/件)，商品件标准重量落入本区间时按此单价计费',
  `sort` int(11) NOT NULL DEFAULT 0 COMMENT '阶梯排序号，按件标准重量从小到大递增，便于列表展示与连续性校验',
  `create_user_id` bigint(20) NULL COMMENT '创建人ID',
  `create_user_name` varchar(64) NULL COMMENT '创建人姓名',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_user_id` bigint(20) NULL COMMENT '更新人ID',
  `update_user_name` varchar(64) NULL COMMENT '更新人姓名',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bigint(20) NOT NULL DEFAULT 0 COMMENT '是否删除 0正常 非0删除',
  PRIMARY KEY (`id`),
  KEY `nk_template` (`template_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='计费规则阶梯：一个模板下按商品件标准重量划分多个左开右闭区间，每区间一个件单价，区间需连续不重叠'
;

CREATE TABLE `demeter_pickup_fee_rule_template` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `company_id` bigint(20) NOT NULL COMMENT '企业ID，规则模板按企业隔离，来源当前登录运营所属企业',
  `template_name` varchar(50) NOT NULL COMMENT '规则模板名称，同企业内有效记录唯一，便于运营识别（如「袋装食品-通用阶梯」）',
  `charge_mode` varchar(16) NOT NULL DEFAULT 'LADDER' COMMENT '计费方式：LADDER=按件阶梯计费',
  `discount_threshold_qty` int(11) NULL COMMENT '达标件数：商家当日该车队揽收总件数（销售+退货）达到此值才享折扣；为空表示无折扣门槛',
  `discount_rate` decimal(5,2) NULL COMMENT '达标折扣率(%)，如85表示85折；取值范围0<rate<100；须与discount_threshold_qty同时填写或同时为空',
  `status` varchar(16) NOT NULL DEFAULT 'ENABLE' COMMENT '规则状态：ENABLE=启用，DISABLE=禁用；禁用后不可被车队配置引用，已被引用的不可禁用',
  `remark` varchar(255) NULL COMMENT '备注说明',
  `create_user_id` bigint(20) NULL COMMENT '创建人ID（运营人员用户ID）',
  `create_user_name` varchar(64) NULL COMMENT '创建人姓名',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_user_id` bigint(20) NULL COMMENT '更新人ID',
  `update_user_name` varchar(64) NULL COMMENT '更新人姓名',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bigint(20) NOT NULL DEFAULT 0 COMMENT '是否删除 0正常 非0删除',
  PRIMARY KEY (`id`),
  KEY `nk_company` (`company_id`),
  UNIQUE KEY `uk_company_template_name` (`company_id`, `template_name`, `deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='采师费计费规则模板：定义一个车队共用的阶梯计费与达标折扣规则，被车队配置引用'
;

CREATE TABLE `demeter_pickup_fleet_config` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `company_id` bigint(20) NOT NULL COMMENT '企业ID，车队配置按企业隔离，来源tms.tms_fleet.company_id',
  `fleet_id` bigint(20) NULL COMMENT 'tms车队ID，来源tms.tms_fleet.id，通过接口①选择带入',
  `enterprise_entity_id` bigint(20) NULL COMMENT '企业实体ID',
  `fleet_code` varchar(32) NOT NULL COMMENT '车队编码，来源tms.tms_fleet.fleet_code，全局唯一，作为业务主键贯穿明细与账单',
  `fleet_name` varchar(128) NOT NULL COMMENT '车队名称，来源tms.tms_fleet.fleet_name',
  `leader_name` varchar(50) NOT NULL COMMENT '车队联系人姓名，来源tms.tms_fleet，只读，由联系人同步Job自动更新',
  `leader_phone` varchar(20) NOT NULL COMMENT '车队联系人电话，来源tms.tms_fleet，只读，由联系人同步Job自动更新',
  `rule_template_id` bigint(20) NULL COMMENT '关联计费规则模板ID，关联demeter_pickup_fee_rule_template.id；启用时必填且模板须为启用状态',
  `platform_split_rate` decimal(5,2) NOT NULL COMMENT '平台分账比例(%)，如5表示平台抽佣5%、采师实得95%；落账单时冗余快照',
  `status` varchar(16) NOT NULL DEFAULT 'DISABLE' COMMENT '启用状态：ENABLE=启用，DISABLE=禁用；启用须cert_status=CERTIFIED且模板启用；车队未绑定采师时才可禁用',
  `create_user_id` bigint(20) NULL COMMENT '创建人ID（新增该车队配置的运营人员）',
  `create_user_name` varchar(64) NULL COMMENT '创建人姓名',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_user_id` bigint(20) NULL COMMENT '更新人ID（最后维护该车队配置的用户）',
  `update_user_name` varchar(64) NULL COMMENT '更新人姓名',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bigint(20) NOT NULL DEFAULT 0 COMMENT '是否删除 0正常 非0删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_company_fleet_code` (`fleet_code`, `deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='采师车队配置'
;

CREATE TABLE `demeter_pickup_fleet_config_log` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `fleet_config_id` bigint(20) NOT NULL COMMENT '关联车队配置ID，关联demeter_pickup_fleet_config.id',
  `operate_type` varchar(32) NOT NULL COMMENT '操作类型：ADD=新增车队配置，EDIT=编辑，ENABLE=启用，DISABLE=禁用，CERTIFY=进件，USER_ADD=新增用户，USER_DEL=删除用户，USER_ROLE=设置管理员，USER_PWD=重置密码，USER_UNBIND=清微信',
  `operate_content` text NULL COMMENT '操作内容：字段级变更前后值JSON，如 {"leader_phone":{"before":"13800","after":"13900"}}',
  `operate_user_id` bigint(20) NULL COMMENT '操作人ID（执行本次操作的用户）',
  `operate_user_name` varchar(64) NULL COMMENT '操作人姓名（冗余，便于日志展示）',
  `operate_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '操作时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '记录创建时间',
  PRIMARY KEY (`id`),
  KEY `nk_fleet` (`fleet_config_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='车队配置操作日志'
;

CREATE TABLE `demeter_pickup_fleet_user` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `fleet_config_id` bigint(20) NOT NULL COMMENT '所属车队配置ID，关联demeter_pickup_fleet_config.id',
  `picker_user_id` bigint(20) NOT NULL COMMENT '采师ID，来源tms.driver.id（即purchaserId，通过接口②选择带入）',
  `picker_user_name` varchar(64) NULL COMMENT '采师姓名（冗余字段，便于列表展示）',
  `phone` varchar(20) NOT NULL COMMENT '采师联系电话，用于采师小程序登录账号',
  `role` varchar(16) NOT NULL COMMENT '车队用户角色：ADMIN=管理员（可管理车队用户、查看账单），GENERAL=一般用户（仅查看账单）',
  `password` varchar(128) NULL COMMENT '登录密码（加密存储），可由管理员重置',
  `wechat_open_id` varchar(128) NULL COMMENT '微信openId，用于采师小程序微信登录；为空表示未绑定，管理员可清空解绑',
  `status` varchar(16) NOT NULL DEFAULT 'ENABLE' COMMENT '用户状态：ENABLE=启用，DISABLE=禁用',
  `create_user_id` bigint(20) NULL COMMENT '创建人ID（新增该采师用户的管理员）',
  `create_user_name` varchar(64) NULL COMMENT '创建人姓名',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_user_id` bigint(20) NULL COMMENT '更新人ID（最后维护该用户的用户）',
  `update_user_name` varchar(64) NULL COMMENT '更新人姓名',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bigint(20) NOT NULL DEFAULT 0 COMMENT '是否删除 0正常 非0删除',
  `company_id` bigint(20) NULL COMMENT '省区ID',
  PRIMARY KEY (`id`),
  KEY `nk_picker_user` (`picker_user_id`, `deleted`, `id`),
  UNIQUE KEY `uk_fleet_picker` (`fleet_config_id`, `picker_user_id`, `deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='采师车队用户：此车队下的采师账号，区分管理员与一般用户，用于采师小程序登录与账单查看'
;

CREATE TABLE `demeter_provisions_account_top_up_call_back_log` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `order_no` varchar(255) NOT NULL,
  `merchant_no` varchar(100) NOT NULL,
  `amount` decimal(12,2) NOT NULL,
  `call_time` datetime NOT NULL,
  `call_content` longtext NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `order_no_uk` (`order_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4
;

CREATE TABLE `demeter_refund_callback_compensate` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `biz_refund_apply_no` varchar(50) NOT NULL COMMENT '业务退款单号',
  `ret_status` varchar(255) NULL COMMENT '第三方状态',
  `status` varchar(32) NOT NULL DEFAULT 'INIT' COMMENT '处理状态 INIT：未处理，DOING：处理中，SUCCESS：处理成功',
  `fail_reason` varchar(255) NULL COMMENT '失败原因',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_biz_refund_apply_no` (`biz_refund_apply_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4
;

CREATE TABLE `demeter_refund_failure_record` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `merchant_no` varchar(16) NOT NULL COMMENT '用户编号',
  `merchant_user_name` varchar(128) NOT NULL COMMENT '用户名称',
  `refund_date` varchar(8) NOT NULL COMMENT '退汇日期',
  `refund_time` varchar(8) NOT NULL COMMENT '退汇时间',
  `refund_reason` varchar(128) NOT NULL COMMENT '退汇原因',
  `channel_serial_no` varchar(64) NOT NULL COMMENT '原系统流水号',
  `cash_date` varchar(8) NOT NULL COMMENT '原提现日期',
  `account_name` varchar(128) NOT NULL COMMENT '原用户账户户名',
  `account_bank_no` varchar(32) NOT NULL COMMENT '原银行卡号/账号',
  `amount` decimal(17,2) NOT NULL COMMENT '原清分/提现金额',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `channel_serial_no` (`channel_serial_no`),
  KEY `merchant_no` (`merchant_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='中信银行退汇失败记录'
;

CREATE TABLE `demeter_refund_order` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `refund_order_no` varchar(64) NOT NULL DEFAULT '' COMMENT '退款单号',
  `after_sale_no` varchar(64) NOT NULL DEFAULT '' COMMENT '售后单号',
  `order_id` bigint(20) NOT NULL COMMENT '订单ID',
  `order_no` varchar(64) NOT NULL DEFAULT '' COMMENT '订单号',
  `order_item_id` varchar(1024) NOT NULL COMMENT '订单项ID(冗余)',
  `temp_order_clearing_id` bigint(20) NOT NULL COMMENT '临时清分ID',
  `refund_amount` decimal(8,2) NULL COMMENT '退款金额',
  `order_payment_no` varchar(64) NULL COMMENT '自身订单付款单编号',
  `payment_serial_number` varchar(64) NOT NULL DEFAULT '' COMMENT '支付流水号',
  `refund_order_status` varchar(64) NOT NULL COMMENT '退款单状态',
  `refund_order_origin_type` varchar(64) NOT NULL COMMENT '退款单来源的类型',
  `origin_order_payment_no` varchar(64) NOT NULL DEFAULT '' COMMENT '原始订单付款单编号',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_after_sale_no` (`after_sale_no`),
  KEY `order_id_index` (`order_id`),
  KEY `order_no_index` (`order_no`),
  UNIQUE KEY `order_payment_no_unique` (`order_payment_no`),
  KEY `refund_order_no_index` (`refund_order_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='退款单'
;

CREATE TABLE `demeter_seller_settlement_info_adjust_log` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `seller_id` bigint(20) NOT NULL COMMENT '卖家ID',
  `merchant_user_type` varchar(100) NOT NULL DEFAULT 'SELLER' COMMENT '商户账号类型',
  `settlement_info_log` text NULL COMMENT '结算信息日志',
  `create_user_id` int(11) NOT NULL COMMENT '创建用户ID',
  `create_user_name` varchar(30) NOT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='卖家结算信息调整日志记录表'
;

CREATE TABLE `demeter_snapshot_log` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `biz_id` bigint(20) NOT NULL COMMENT '业务id',
  `biz_type` varchar(50) NOT NULL COMMENT '业务编码',
  `action_user_id` bigint(20) NOT NULL COMMENT '操作人id',
  `action_user_name` varchar(50) NOT NULL COMMENT '操作人name',
  `action_time` datetime NOT NULL COMMENT '操作时间',
  `action_type` varchar(50) NOT NULL COMMENT '操作类别',
  `snapshot_detail` longtext NOT NULL COMMENT '快照',
  PRIMARY KEY (`id`),
  KEY `idx` (`biz_type`, `biz_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4
;

CREATE TABLE `demeter_suning_balance` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `statistics_time` datetime NOT NULL COMMENT '统计时间',
  `merchant_total_balance` decimal(18,2) NOT NULL COMMENT '商户账户总余额',
  `suning_total_amount` decimal(18,2) NOT NULL COMMENT '冻结余额',
  `difference` decimal(18,2) NOT NULL COMMENT '差额',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_statistic_time` (`statistics_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='苏宁银行账户总金额统计'
;

CREATE TABLE `demeter_sys_config` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `type` varchar(32) NOT NULL COMMENT '类型',
  `config_key` varchar(64) NOT NULL COMMENT '键',
  `config_value` varchar(2048) NOT NULL COMMENT '值',
  `sort` int(11) NOT NULL COMMENT '排序',
  `status` int(11) NOT NULL COMMENT '状态',
  `description` varchar(2048) NOT NULL COMMENT '描述',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_type_config_key` (`type`, `config_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='系统数据配置表'
;

CREATE TABLE `demeter_sys_config_company` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `company_id` bigint(20) NOT NULL COMMENT '公司ID',
  `type` varchar(32) NOT NULL COMMENT '类型',
  `config_key` varchar(64) NOT NULL COMMENT '键',
  `config_value` text NOT NULL COMMENT '值',
  `sort` int(11) NOT NULL COMMENT '排序',
  `status` int(11) NOT NULL COMMENT '状态',
  `description` varchar(2048) NOT NULL COMMENT '描述',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_company_type_config_key` (`company_id`, `type`, `config_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='公司级系统数据配置表'
;

CREATE TABLE `express_payment_order` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `tenant_no` varchar(32) NOT NULL COMMENT '租户号',
  `company_id` bigint(20) NOT NULL COMMENT '订单所属运营企业ID',
  `order_no` varchar(64) NOT NULL COMMENT '物流订单号',
  `order_type` varchar(16) NULL COMMENT '物流订单类型：HELP_TAKE-帮取，HELP_SEND-帮送',
  `out_trade_no` varchar(64) NOT NULL COMMENT '微信商户订单号，每次支付唯一',
  `transaction_id` varchar(64) NULL COMMENT '微信支付订单号',
  `app_id` varchar(64) NOT NULL COMMENT '微信小程序AppID',
  `user_id` bigint(20) NOT NULL COMMENT '发起支付的普通用户ID',
  `payer_name` varchar(64) NULL COMMENT '发起支付时的付款人姓名快照',
  `payer_mobile` varchar(32) NULL COMMENT '发起支付时的付款人手机号快照',
  `amount` decimal(12,2) NOT NULL COMMENT '服务端复核支付金额（元）',
  `status` varchar(16) NOT NULL COMMENT 'PENDING-待支付，PAID-已支付，CANCELLED-已关单，FAILED-失败',
  `failure_code` varchar(64) NULL COMMENT '支付失败码',
  `failure_message` varchar(255) NULL COMMENT '支付失败原因，不保存敏感报文',
  `pay_time` datetime NULL COMMENT '微信支付成功时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bigint(20) NOT NULL DEFAULT 0 COMMENT '逻辑删除标识：0-未删除，非0-已删除记录ID',
  PRIMARY KEY (`id`),
  KEY `nk_tenant_company_created` (`tenant_no`, `company_id`, `deleted`, `create_time`, `id`),
  KEY `nk_tenant_company_payer_created` (`tenant_no`, `company_id`, `payer_mobile`, `deleted`, `create_time`, `id`),
  KEY `nk_tenant_order_status_id` (`tenant_no`, `order_no`, `status`, `id`),
  KEY `nk_tenant_user_create_time` (`tenant_no`, `user_id`, `create_time`),
  UNIQUE KEY `uk_out_trade_no` (`out_trade_no`),
  UNIQUE KEY `uk_transaction_id` (`transaction_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='快运微信支付单（不参与清分）'
;

CREATE TABLE `ods_casaba_demeter_citic_settlement_daily_summary` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `batch_id` char(24) NOT NULL COMMENT '批次号',
  `company_id` bigint(20) NULL COMMENT '企业id',
  `merchant_id` bigint(20) NULL COMMENT '商户id',
  `merchant_no` varchar(50) NULL COMMENT '商户编号',
  `begin_bill_date` date NOT NULL COMMENT '账单开始日期',
  `end_bill_date` date NOT NULL COMMENT '账单结束日期',
  `pay_amount` decimal(10,2) NULL COMMENT '订单支付金额',
  `refund_amount` decimal(10,2) NULL COMMENT '订单退款金额',
  `net_amount` decimal(10,2) NOT NULL COMMENT '费用/分账净额',
  `split_fee_type` varchar(50) NOT NULL COMMENT '分账类型',
  `transaction_type` varchar(50) NOT NULL COMMENT '资金方向',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_batch_id` (`batch_id`),
  KEY `idx_create_time` (`create_time`),
  KEY `uk_begin_date_end_date_merchant_no` (`company_id`, `begin_bill_date`, `end_bill_date`, `merchant_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='待分账费用类型统计表'
;

CREATE TABLE `payment_method_detail` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `company_id` bigint(20) NULL COMMENT '企业ID',
  `payment_order_serial_no` varchar(64) NOT NULL COMMENT '支付申请流水号',
  `trade_type` varchar(32) NOT NULL DEFAULT '' COMMENT '申请类型, PAY-支付，REFUND-退款',
  `out_apply_no` varchar(64) NOT NULL DEFAULT '' COMMENT '外部支付申请号',
  `out_transaction_id` varchar(64) NULL COMMENT '外部交易号',
  `amount` decimal(10,2) NOT NULL COMMENT '请求金额',
  `pay_method` varchar(64) NOT NULL COMMENT '支付方式',
  `status` varchar(32) NOT NULL COMMENT '支付状态',
  `complete_time` datetime NULL COMMENT '支付完成时间',
  `fail_reason` varchar(512) NULL COMMENT '失败原因',
  `gateway_resp` text NULL COMMENT '第三方支付网关返回报文',
  `extension` text NULL COMMENT '扩展参数',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '最后修改时间',
  PRIMARY KEY (`id`),
  KEY `idx_out_apply_no` (`out_apply_no`),
  UNIQUE KEY `uk_serialno_outapplyno` (`payment_order_serial_no`, `out_apply_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='支付申请明细'
;

CREATE TABLE `payment_order` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `serial_no` varchar(64) NOT NULL COMMENT '支付/退款订单号',
  `original_serial_no` varchar(128) NOT NULL DEFAULT '' COMMENT '退款订单专用，指向支付订单流水号',
  `company_id` bigint(20) NOT NULL COMMENT '企业ID',
  `trade_type` varchar(32) NULL COMMENT '申请类型, PAY-支付，REFUND-退款',
  `status` varchar(32) NULL COMMENT '状态',
  `trade_order_no` varchar(128) NOT NULL COMMENT '业务付款申请号',
  `biz_type` varchar(32) NOT NULL COMMENT '调用支付的业务域/业务类型',
  `order_pay_title` varchar(128) NULL COMMENT '订单尾款/订单尾款-平台自动支付/订单尾款-少补 等',
  `amount` decimal(10,2) NOT NULL COMMENT '付款金额',
  `user_id` bigint(20) NOT NULL COMMENT '支付人id',
  `user_name` varchar(50) NOT NULL COMMENT '支付人姓名',
  `user_phone` varchar(20) NOT NULL COMMENT '支付人手机号',
  `extension` text NULL COMMENT '扩展信息',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '最后修改时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `NK_biz_no` (`trade_order_no`),
  KEY `NK_create_time_company_id_serial_no` (`create_time`, `company_id`, `serial_no`),
  KEY `NK_original_serial_no` (`original_serial_no`),
  UNIQUE KEY `uk_serial_no` (`serial_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='付款申请'
;

CREATE TABLE `payment_split` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'id',
  `company_id` bigint(20) NULL COMMENT '企业ID',
  `payment_order_serial_no` varchar(64) NULL COMMENT '支付订单流水号',
  `biz_no` varchar(64) NULL COMMENT '业务单号',
  `biz_type` varchar(64) NULL COMMENT '业务类型',
  `merchant_id` bigint(20) NULL COMMENT '分账商户ID',
  `merchant_no` varchar(64) NULL,
  `merchant_sign_name` varchar(64) NULL COMMENT '分账商户签约名称',
  `payment_method` varchar(64) NOT NULL COMMENT '支付方式，由订单指定',
  `amount` decimal(10,2) NULL COMMENT '金额',
  `extension` text NULL COMMENT '扩展参数',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '最后修改时间',
  PRIMARY KEY (`id`),
  KEY `NK_payment_order_serial_no_merchant_id` (`payment_order_serial_no`, `merchant_id`),
  KEY `idx_biz_no` (`biz_no`),
  KEY `idx_company_id` (`company_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='分账记录表'
;

CREATE TABLE `payment_v2_callback_log` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `out_apply_no` varchar(64) NOT NULL COMMENT '外部支付申请号',
  `payment_order_serial_no` varchar(64) NULL COMMENT '支付订单流水号',
  `transaction_id` varchar(128) NULL COMMENT '外部交易号',
  `money_order` decimal(16,2) NULL COMMENT '订单金额',
  `result_pay` varchar(32) NULL COMMENT '支付结果',
  `callback_content` text NULL COMMENT '回调原始报文',
  `callback_way` varchar(32) NOT NULL COMMENT '回调方式',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_out_apply_no` (`out_apply_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='V2版支付回调日志'
;

CREATE TABLE `risk_audit_batch` (
  `batch_id` bigint(20) NOT NULL COMMENT '批次唯一 ID',
  `target_id` bigint(20) NULL COMMENT '目标对象 ID（如：门店 ID）',
  `trigger_source` varchar(32) NULL COMMENT '触发来源（如：STORE_ENTRY, INFO_UPDATE）',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '触发时间',
  PRIMARY KEY (`batch_id`),
  KEY `NK_batch_target` (`batch_id`, `target_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='校验批次表：记录一次完整的风控触发'
;

CREATE TABLE `risk_strategy_result` (
  `id` bigint(20) NOT NULL COMMENT '主键',
  `batch_id` bigint(20) NULL COMMENT '关联批次 ID',
  `strategy_code` varchar(64) NULL COMMENT '策略编码（PHONE_VALID, AUTH_VERIFY, CROSS_CHECK）',
  `strategy_version` varchar(16) NULL COMMENT 'Agent 版本号',
  `result_content` varchar(500) NULL COMMENT '核心字段：存储策略的完整输出 JSON',
  PRIMARY KEY (`id`),
  KEY `NK_batch_id` (`batch_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='策略结果明细表：通过 strategy_code 区分策略，result_content 存储异构数据'
;
